    identityVault = mysqlTable("identity_vault", {
      id: int("id").primaryKey().autoincrement(),
      houseId: int("house_id").notNull(),
      houseMemberId: int("house_member_id"),
      // References houseMembers.id (nullable for non-system family)
      heirId: int("heir_id"),
      // References houseHeirs.id (for heirs who aren't system users)
      // Display layer reference (what the system shows)
      displayAlias: varchar("display_alias", { length: 255 }).notNull(),
      // The alias/title shown in UI
      displayRole: varchar("display_role", { length: 100 }),
      // "Head of House", "Co-Head", "Heir", etc.
      // Encrypted legal identity (AES-256-GCM)
      // All encrypted fields store: iv:authTag:ciphertext (base64 encoded)
      encryptedLegalName: text("encrypted_legal_name"),
      // Full legal name
      encryptedSsn: text("encrypted_ssn"),
      // Social Security Number or EIN
      encryptedDob: text("encrypted_dob"),
      // Date of birth
      encryptedAddress: text("encrypted_address"),
      // Legal/mailing address
      encryptedPhone: text("encrypted_phone"),
      // Phone number
      encryptedEmail: text("encrypted_email"),
      // Personal email
      encryptedNotes: text("encrypted_notes"),
      // Additional sensitive notes
      // Trust/Inheritance designations (encrypted)
      encryptedTrustBeneficiary: text("encrypted_trust_beneficiary"),
      // Beneficiary designation details
      inheritancePercentage: decimal("inheritance_percentage", { precision: 5, scale: 2 }),
      // Not encrypted - needed for calculations
      inheritanceOrder: int("inheritance_order"),
      // Birth order / priority for inheritance
      // Relationship to House head
      relationship: mysqlEnum("relationship", [
        "self",
        "spouse",
        "child",
        "grandchild",
        "sibling",
        "niece_nephew",
        "cousin",
        "adopted",
        "guardian_ward",
        "other"
      ]).notNull(),
      // Vault access tracking
      lastAccessedAt: timestamp("last_accessed_at"),
      lastAccessedBy: int("last_accessed_by"),
      // Should always be House owner
      accessCount: int("access_count").default(0).notNull(),
      // Encryption metadata
      encryptionVersion: int("encryption_version").default(1).notNull(),
      // For key rotation
      encryptionKeyId: varchar("encryption_key_id", { length: 100 }),
      // Which key was used
      // Status
      status: mysqlEnum("vault_status", ["active", "locked", "archived"]).default("active").notNull(),
      createdAt: timestamp("created_at").defaultNow().notNull(),
      updatedAt: timestamp("updated_at").defaultNow().onUpdateNow().notNull()
    });
    vaultAccessLog = mysqlTable("vault_access_log", {
      id: int("id").primaryKey().autoincrement(),
      houseId: int("house_id").notNull(),
      vaultEntryId: int("vault_entry_id").notNull(),
      // References identityVault.id
      accessedByUserId: int("accessed_by_user_id").notNull(),
      // Access details
      accessType: mysqlEnum("access_type", [
        "view",
        // Viewed decrypted data
        "create",
        // Created new vault entry
        "update",
        // Updated vault entry
        "export",
        // Exported for legal documents
        "emergency"
        // Emergency access (logged with extra detail)
      ]).notNull(),
      fieldsAccessed: json("fields_accessed").$type(),
      // Which fields were decrypted
      ipAddress: varchar("ip_address", { length: 45 }),
      userAgent: text("user_agent"),
      // Verification
      authMethod: mysqlEnum("auth_method", [
        "vault_pin",
        // Separate PIN for vault access
        "password_reentry",
        // Re-entered password
        "biometric",
        // Future: biometric verification
        "emergency_key"
        // Emergency access key
      ]).notNull(),
      accessedAt: timestamp("accessed_at").defaultNow().notNull()
    });
