var delegationReasonEnum = z24.enum(["workload", "expertise", "pto", "priority", "reassignment", "collaboration", "other"]);
var taskTypeEnum = z24.enum(["article", "signature", "approval", "review", "analysis", "compliance"]);
var priorityEnum = z24.enum(["low", "medium", "high", "critical"]);
async function createDelegationNotification(db7, userId, type, taskTitle, fromUserName, toUserName, metadata) {
  const notificationTitles = {
    delegated_to_you: "Task Delegated to You",
    delegation_accepted: "Delegation Accepted",
    delegation_declined: "Delegation Declined",
    delegation_completed: "Delegated Task Completed",
    approval_required: "Delegation Approval Required",
    approval_granted: "Delegation Approved",
    approval_rejected: "Delegation Rejected"
  };
  const notificationMessages = {
    delegated_to_you: `${fromUserName} delegated "${taskTitle}" to you`,
    delegation_accepted: `${toUserName} accepted your delegation of "${taskTitle}"`,
    delegation_declined: `${toUserName} declined your delegation of "${taskTitle}"`,
    delegation_completed: `${toUserName} completed "${taskTitle}"`,
    approval_required: `${fromUserName} requests approval to delegate "${taskTitle}" to ${toUserName}`,
    approval_granted: `Your delegation of "${taskTitle}" has been approved`,
    approval_rejected: `Your delegation of "${taskTitle}" was rejected`
  };
  await db7.insert(notifications).values({
    userId,
    type: type === "approval_required" ? "approval" : "operation",
    title: notificationTitles[type],
    message: notificationMessages[type],
    actionUrl: "/task-delegation",
    isPriority: type === "approval_required" || type === "delegated_to_you",
    metadata: {
      delegationType: type,
      taskTitle,
      fromUserName,
      toUserName,
      ...metadata
    },
    isRead: false,
    createdAt: /* @__PURE__ */ new Date()
  });
}
var delegationRouter = router({
  /**
   * Create a new delegation request
   */
  create: protectedProcedure.input(z24.object({
    taskId: z24.string(),
    taskType: taskTypeEnum,
    taskTitle: z24.string(),
    toUserId: z24.number(),
    reason: delegationReasonEnum,
    notes: z24.string().optional(),
    originalDueDate: z24.date(),
    newDueDate: z24.date().optional(),
    priority: priorityEnum.default("medium"),
    requiresApproval: z24.boolean().default(false)
  })).mutation(async ({ ctx, input }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database unavailable");
    const fromUser = ctx.user;
    const [toUser] = await db7.select().from(users).where(eq23(users.id, input.toUserId));
    if (!toUser) throw new Error("Target user not found");
    const needsApproval = input.requiresApproval || input.priority === "critical" || input.priority === "high";
    const delegationId = `del-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    const status = needsApproval ? "pending_approval" : "pending";
    if (needsApproval) {
      const managers = await db7.select().from(users).where(
        or2(eq23(users.role, "admin"), eq23(users.role, "staff"))
      );
      for (const manager of managers) {
        if (manager.id !== fromUser.id) {
          await createDelegationNotification(
            db7,
            manager.id,
            "approval_required",
            input.taskTitle,
            fromUser.name || "Unknown",
            toUser.name || "Unknown",
            { delegationId, taskId: input.taskId, priority: input.priority }
          );
        }
      }
    } else {
      await createDelegationNotification(
        db7,
        input.toUserId,
        "delegated_to_you",
        input.taskTitle,
        fromUser.name || "Unknown",
        toUser.name || "Unknown",
        { delegationId, taskId: input.taskId, reason: input.reason, notes: input.notes }
      );
    }
    return {
      success: true,
      delegationId,
      status,
      needsApproval,
      message: needsApproval ? "Delegation submitted for manager approval" : "Delegation request sent successfully"
    };
  }),
  /**
   * Respond to a delegation (accept/decline)
   */
  respond: protectedProcedure.input(z24.object({
    delegationId: z24.string(),
    taskId: z24.string(),
    taskTitle: z24.string(),
    fromUserId: z24.number(),
    action: z24.enum(["accept", "decline"]),
    declineReason: z24.string().optional()
  })).mutation(async ({ ctx, input }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database unavailable");
    const toUser = ctx.user;
    const [fromUser] = await db7.select().from(users).where(eq23(users.id, input.fromUserId));
    if (!fromUser) throw new Error("Original delegator not found");
    const notificationType = input.action === "accept" ? "delegation_accepted" : "delegation_declined";
    await createDelegationNotification(
      db7,
      input.fromUserId,
      notificationType,
      input.taskTitle,
      fromUser.name || "Unknown",
      toUser.name || "Unknown",
      { delegationId: input.delegationId, declineReason: input.declineReason }
    );
    return {
      success: true,
      status: input.action === "accept" ? "accepted" : "declined",
      message: input.action === "accept" ? "Delegation accepted successfully" : "Delegation declined"
    };
  }),
  /**
   * Mark a delegated task as completed
   */
  complete: protectedProcedure.input(z24.object({
    delegationId: z24.string(),
    taskId: z24.string(),
    taskTitle: z24.string(),
    fromUserId: z24.number(),
    completionNotes: z24.string().optional()
  })).mutation(async ({ ctx, input }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database unavailable");
    const toUser = ctx.user;
    const [fromUser] = await db7.select().from(users).where(eq23(users.id, input.fromUserId));
    if (!fromUser) throw new Error("Original delegator not found");
    await createDelegationNotification(
      db7,
      input.fromUserId,
      "delegation_completed",
      input.taskTitle,
      fromUser.name || "Unknown",
      toUser.name || "Unknown",
      { delegationId: input.delegationId, completionNotes: input.completionNotes }
    );
    return {
      success: true,
      status: "completed",
      message: "Task marked as completed"
    };
  }),
  /**
   * Approve or reject a delegation request (manager only)
   */
  approveOrReject: protectedProcedure.input(z24.object({
    delegationId: z24.string(),
    taskId: z24.string(),
    taskTitle: z24.string(),
    fromUserId: z24.number(),
    toUserId: z24.number(),
    action: z24.enum(["approve", "reject"]),
    reason: z24.string().optional()
  })).mutation(async ({ ctx, input }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database unavailable");
    if (ctx.user.role !== "admin" && ctx.user.role !== "staff") {
      throw new Error("Only managers can approve or reject delegations");
    }
    const [fromUser] = await db7.select().from(users).where(eq23(users.id, input.fromUserId));
    const [toUser] = await db7.select().from(users).where(eq23(users.id, input.toUserId));
    if (!fromUser || !toUser) throw new Error("Users not found");
    if (input.action === "approve") {
      await createDelegationNotification(
        db7,
        input.fromUserId,
        "approval_granted",
        input.taskTitle,
        fromUser.name || "Unknown",
        toUser.name || "Unknown",
        { delegationId: input.delegationId, approvedBy: ctx.user.name }
      );
      await createDelegationNotification(
        db7,
        input.toUserId,
        "delegated_to_you",
        input.taskTitle,
        fromUser.name || "Unknown",
        toUser.name || "Unknown",
        { delegationId: input.delegationId }
      );
    } else {
      await createDelegationNotification(
        db7,
        input.fromUserId,
        "approval_rejected",
        input.taskTitle,
        fromUser.name || "Unknown",
        toUser.name || "Unknown",
        { delegationId: input.delegationId, rejectedBy: ctx.user.name, reason: input.reason }
      );
    }
    return {
      success: true,
      status: input.action === "approve" ? "approved" : "rejected",
      message: input.action === "approve" ? "Delegation approved and sent to recipient" : "Delegation rejected"
    };
  }),
  /**
   * Get pending approval requests (for managers)
   */
  getPendingApprovals: protectedProcedure.query(async ({ ctx }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database unavailable");
    if (ctx.user.role !== "admin" && ctx.user.role !== "staff") {
      return { approvals: [] };
    }
    const approvalNotifications = await db7.select().from(notifications).where(and10(
      eq23(notifications.userId, ctx.user.id),
      eq23(notifications.type, "approval"),
      eq23(notifications.isRead, false)
    )).orderBy(desc5(notifications.createdAt));
    return {
      approvals: approvalNotifications.map((n) => ({
        id: n.id,
        delegationId: n.metadata?.delegationId,
        taskId: n.metadata?.taskId,
        taskTitle: n.metadata?.taskTitle,
        fromUserName: n.metadata?.fromUserName,
        toUserName: n.metadata?.toUserName,
        priority: n.metadata?.priority,
        createdAt: n.createdAt
      }))
    };
  }),
  /**
   * Get team workload data
   */
  getTeamWorkload: protectedProcedure.input(z24.object({
    department: z24.string().optional()
  }).optional()).query(async ({ ctx }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database unavailable");
    const teamMembers = await db7.select({
      id: users.id,
      name: users.name,
      email: users.email,
      role: users.role
    }).from(users);
    const workloadData = await Promise.all(teamMembers.map(async (member) => {
      const [pendingCount] = await db7.select({ count: sql4`count(*)` }).from(notifications).where(and10(
        eq23(notifications.userId, member.id),
        eq23(notifications.isRead, false)
      ));
      const pendingTasks = pendingCount?.count ?? 0;
      const maxTasks = 10;
      const utilization = Math.min(100, Math.round(pendingTasks / maxTasks * 100));
      let status;
      if (utilization < 50) status = "available";
      else if (utilization < 75) status = "balanced";
      else if (utilization < 90) status = "busy";
      else status = "overloaded";
      return {
        id: member.id,
        name: member.name || "Unknown",
        email: member.email || "",
        role: member.role,
        workload: {
          pendingTasks,
          overdueTasks: Math.floor(Math.random() * 3),
          // Simulated
          completedThisWeek: Math.floor(Math.random() * 10) + 3
          // Simulated
        },
        capacity: {
          maxTasks,
          currentUtilization: utilization,
          availableCapacity: Math.max(0, maxTasks - pendingTasks),
          status
        }
      };
    }));
    return { teamMembers: workloadData };
  }),
  /**
   * Get delegation analytics
   */
  getAnalytics: protectedProcedure.input(z24.object({
    days: z24.number().min(1).max(365).default(30)
  }).optional()).query(async ({ ctx, input }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database unavailable");
    const days = input?.days ?? 30;
    const cutoffDate = new Date(Date.now() - days * 24 * 60 * 60 * 1e3);
    const delegationNotifications = await db7.select().from(notifications).where(and10(
      eq23(notifications.type, "operation"),
      sql4`${notifications.createdAt} >= ${cutoffDate}`
    )).orderBy(desc5(notifications.createdAt));
    const total = delegationNotifications.length;
    const accepted = delegationNotifications.filter(
      (n) => n.metadata?.delegationType === "delegation_accepted"
    ).length;
    const declined = delegationNotifications.filter(
      (n) => n.metadata?.delegationType === "delegation_declined"
    ).length;
    const completed = delegationNotifications.filter(
      (n) => n.metadata?.delegationType === "delegation_completed"
    ).length;
    return {
      metrics: {
        totalDelegations: total,
        acceptanceRate: total > 0 ? accepted / total * 100 : 0,
        declineRate: total > 0 ? declined / total * 100 : 0,
        completionRate: accepted > 0 ? completed / accepted * 100 : 0,
        avgResponseTime: 12,
        // Simulated hours
        avgCompletionTime: 48,
        // Simulated hours
        onTimeCompletionRate: 85
        // Simulated percentage
      },
      period: {
        days,
        startDate: cutoffDate.toISOString(),
        endDate: (/* @__PURE__ */ new Date()).toISOString()
      }
    };
  })
});

