    if (!house) return null;
    const members = await db7.select().from(houseMembers).where(eq28(houseMembers.houseId, input.houseId));
    const businesses = await db7.select({
      link: houseBusinesses,
      business: businessEntities
    }).from(houseBusinesses).leftJoin(businessEntities, eq28(houseBusinesses.businessEntityId, businessEntities.id)).where(eq28(houseBusinesses.houseId, input.houseId));
    const network = await db7.select().from(networkHouses).where(eq28(networkHouses.sourceHouseId, input.houseId));
