async function triggerAutomation(db7, userId, houseId, event) {
  const matchingRules = DEFAULT_AUTOMATION_RULES.filter(
    (rule) => rule.isActive && rule.triggerEvent === event.eventType && rule.triggerEntityType === event.entityType
  );
  for (const rule of matchingRules) {
    let conditionsMet = true;
    if (event.metadata) {
      for (const [key, value] of Object.entries(rule.conditions)) {
        if (event.metadata[key] !== value) {
          conditionsMet = false;
          break;
        }
      }
    }
    if (!conditionsMet) continue;
    for (const action of rule.actions) {
      try {
        switch (action.type) {
          case "log_ledger":
            if (houseId) {
              const account = await db7.select().from(luvLedgerAccounts).where(eq44(luvLedgerAccounts.userId, userId)).limit(1);
              if (account.length) {
                await db7.insert(luvLedgerTransactions).values({
                  fromAccountId: account[0].id,
                  toAccountId: account[0].id,
                  amount: "0",
                  transactionType: action.params.transactionType || "allocation",
                  description: action.params.description || `Automated: ${rule.name}`
                });
              }
            }
            break;
          case "create_task":
            console.log(`[Automation] Would create task: ${action.params.title}`);
            break;
          case "send_notification":
            console.log(`[Automation] Would send notification: ${action.params.title}`);
            break;
          case "create_document":
            console.log(`[Automation] Would create document: ${action.params.templateCode}`);
            break;
        }
      } catch (error) {
        console.error(`[Automation] Error executing action ${action.type}:`, error);
      }
    }
  }
}

