function calculateVolatility(holdings3) {
  return Math.random() * 30;
}
function calculateConcentration(holdings3) {
  const totalValue = holdings3.reduce((sum5, h) => sum5 + h.value, 0);
  const maxHolding = Math.max(...holdings3.map((h) => h.value));
  return maxHolding / totalValue * 100;
}
function calculateDiversification(holdings3) {
  const totalValue = holdings3.reduce((sum5, h) => sum5 + h.value, 0);
  const hIndex = holdings3.reduce((sum5, h) => {
    const weight = h.value / totalValue;
    return sum5 + weight * weight;
  }, 0);
  return (1 - hIndex) * 100;
}
function calculateCorrelation(holdings3) {
  return Math.random() * 0.5;
}
function analyzeSectorAllocation(holdings3) {
  const sectors = {};
  const totalValue = holdings3.reduce((sum5, h) => sum5 + h.value, 0);
  holdings3.forEach((holding) => {
    const sector = holding.sector || "Other";
    sectors[sector] = (sectors[sector] || 0) + holding.value / totalValue * 100;
  });
  return sectors;
}
function calculateSectorConcentration(holdings3) {
  return analyzeSectorAllocation(holdings3);
}
function determineRiskLevel(concentration) {
  const maxConcentration = Math.max(...Object.values(concentration));
  if (maxConcentration > 40) return "high";
  if (maxConcentration > 25) return "medium";
  return "low";
}
function calculateAssetAllocation(holdings3) {
  const allocation = {
    stocks: 0,
    bonds: 0,
    cash: 0,
    alternatives: 0
  };
  const totalValue = holdings3.reduce((sum5, h) => sum5 + h.value, 0);
  holdings3.forEach((holding) => {
    const type = holding.assetType || "stocks";
    allocation[type] = (allocation[type] || 0) + holding.value / totalValue * 100;
  });
  return allocation;
}
function getRecommendedAllocation(riskProfile) {
  const allocations = {
    conservative: { stocks: 40, bonds: 50, cash: 10, alternatives: 0 },
    moderate: { stocks: 60, bonds: 30, cash: 5, alternatives: 5 },
    aggressive: { stocks: 80, bonds: 10, cash: 5, alternatives: 5 }
  };
  return allocations[riskProfile] || allocations.moderate;
}
function calculateAlignmentScore(current, recommended) {
  let totalDifference = 0;
  Object.keys(recommended).forEach((key) => {
    totalDifference += Math.abs((current[key] || 0) - recommended[key]);
  });
  return Math.max(0, 100 - totalDifference);
}
