    const totalCurrentLiabilities = data.liabilities.current.accountsPayable + data.liabilities.current.accruedExpenses + data.liabilities.current.shortTermDebt + data.liabilities.current.deferredRevenue + data.liabilities.current.otherCurrentLiabilities;
