    const totalCOGS = data.costOfGoodsSold.directLabor + data.costOfGoodsSold.materials + data.costOfGoodsSold.otherCOGS;
    const grossProfit = totalRevenue - totalCOGS;
    const totalOperatingExpenses = data.operatingExpenses.salaries + data.operatingExpenses.rent + data.operatingExpenses.utilities + data.operatingExpenses.insurance + data.operatingExpenses.marketing + data.operatingExpenses.professionalFees + data.operatingExpenses.officeSupplies + data.operatingExpenses.travel + data.operatingExpenses.depreciation + data.operatingExpenses.otherOperating;
    const operatingIncome = grossProfit - totalOperatingExpenses;
    const totalOtherIncome = data.otherIncomeExpense.interestIncome + data.otherIncomeExpense.otherIncome;
    const totalOtherExpense = data.otherIncomeExpense.interestExpense + data.otherIncomeExpense.otherExpense;
