// server/routers/e-signature.ts
import { z as z109 } from "zod";
init_db();
import { sql as sql46 } from "drizzle-orm";
var eSignatureRouter = router({
  // Create a signature request
  createRequest: adminProcedure.input(z109.object({
    documentId: z109.number(),
    documentType: z109.string(),
    documentTitle: z109.string(),
    signers: z109.array(z109.object({
      userId: z109.number().optional(),
      name: z109.string(),
      email: z109.string().optional(),
      title: z109.string().optional()
    })),
    expiresInDays: z109.number().default(30)
  })).mutation(async ({ input, ctx }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database not available");
    const expiresAt = /* @__PURE__ */ new Date();
    expiresAt.setDate(expiresAt.getDate() + input.expiresInDays);
    const [request] = await db7.execute(sql46`
        INSERT INTO signature_requests (documentId, documentType, documentTitle, requestedBy, status, expiresAt, createdAt, updatedAt)
        VALUES (${input.documentId}, ${input.documentType}, ${input.documentTitle}, ${ctx.user.id}, 'pending', ${expiresAt}, NOW(), NOW())
      `);
    const requestId = request.insertId;
    for (const signer of input.signers) {
      await db7.execute(sql46`
          INSERT INTO signatures (requestId, signerId, signerName, signerEmail, signerTitle, status, createdAt)
          VALUES (${requestId}, ${signer.userId || 0}, ${signer.name}, ${signer.email || null}, ${signer.title || null}, 'pending', NOW())
        `);
    }
    return { requestId, message: "Signature request created" };
  }),
  // Get pending signature requests for current user
  getMyPendingSignatures: protectedProcedure.query(async ({ ctx }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database not available");
    const [signatures4] = await db7.execute(sql46`
        SELECT s.*, sr.documentTitle, sr.documentType, sr.expiresAt
        FROM signatures s
        JOIN signature_requests sr ON s.requestId = sr.id
        WHERE s.signerId = ${ctx.user.id} AND s.status = 'pending'
        ORDER BY sr.createdAt DESC
      `);
    return signatures4;
  }),
  // Get all signature requests (admin)
  getAllRequests: adminProcedure.input(z109.object({
    status: z109.enum(["pending", "in_progress", "completed", "expired", "cancelled"]).optional()
  }).optional()).query(async ({ input }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database not available");
    let query = sql46`
        SELECT sr.*, 
          (SELECT COUNT(*) FROM signatures WHERE requestId = sr.id AND status = 'signed') as signedCount,
          (SELECT COUNT(*) FROM signatures WHERE requestId = sr.id) as totalSigners
        FROM signature_requests sr
      `;
    if (input?.status) {
      query = sql46`${query} WHERE sr.status = ${input.status}`;
    }
    query = sql46`${query} ORDER BY sr.createdAt DESC`;
    const [requests2] = await db7.execute(query);
    return requests2;
  }),
  // Sign a document
  sign: protectedProcedure.input(z109.object({
    signatureId: z109.number(),
    signatureType: z109.enum(["typed", "drawn", "uploaded"]),
    signatureData: z109.string()
    // Base64 or typed name
  })).mutation(async ({ input, ctx }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database not available");
    const [existing] = await db7.execute(sql46`
        SELECT * FROM signatures WHERE id = ${input.signatureId} AND signerId = ${ctx.user.id}
      `);
    if (!existing.length) {
      throw new Error("Signature not found or not authorized");
    }
    const ipAddress = "127.0.0.1";
    await db7.execute(sql46`
        UPDATE signatures 
        SET signatureType = ${input.signatureType}, 
            signatureData = ${input.signatureData},
            signedAt = NOW(),
            ipAddress = ${ipAddress},
            status = 'signed'
        WHERE id = ${input.signatureId}
      `);
    const sig = existing[0];
    const [remaining] = await db7.execute(sql46`
        SELECT COUNT(*) as count FROM signatures 
        WHERE requestId = ${sig.requestId} AND status = 'pending'
      `);
    if (remaining[0].count === 0) {
      await db7.execute(sql46`
          UPDATE signature_requests 
          SET status = 'completed', completedAt = NOW(), updatedAt = NOW()
          WHERE id = ${sig.requestId}
        `);
    } else {
      await db7.execute(sql46`
          UPDATE signature_requests 
          SET status = 'in_progress', updatedAt = NOW()
          WHERE id = ${sig.requestId} AND status = 'pending'
        `);
    }
    return { success: true, message: "Document signed successfully" };
  }),
  // Decline to sign
  decline: protectedProcedure.input(z109.object({
    signatureId: z109.number(),
    reason: z109.string().optional()
  })).mutation(async ({ input, ctx }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database not available");
    await db7.execute(sql46`
        UPDATE signatures 
        SET status = 'declined', declineReason = ${input.reason || null}
        WHERE id = ${input.signatureId} AND signerId = ${ctx.user.id}
      `);
    return { success: true, message: "Signature declined" };
  }),
  // Get signature request details
  getRequest: protectedProcedure.input(z109.object({ requestId: z109.number() })).query(async ({ input }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database not available");
    const [request] = await db7.execute(sql46`
        SELECT * FROM signature_requests WHERE id = ${input.requestId}
      `);
    const [signatures4] = await db7.execute(sql46`
        SELECT * FROM signatures WHERE requestId = ${input.requestId}
      `);
    return {
      request: request[0],
      signatures: signatures4
    };
  }),
  // Cancel a signature request
  cancelRequest: adminProcedure.input(z109.object({ requestId: z109.number() })).mutation(async ({ input }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database not available");
    await db7.execute(sql46`
        UPDATE signature_requests 
        SET status = 'cancelled', updatedAt = NOW()
        WHERE id = ${input.requestId}
      `);
    return { success: true, message: "Request cancelled" };
  }),
  // Sign a vault document
  signVaultDocument: protectedProcedure.input(z109.object({
    documentId: z109.number(),
    signatureType: z109.enum(["typed", "drawn", "uploaded"]),
    signatureData: z109.string(),
    signerName: z109.string(),
    signerTitle: z109.string().optional()
  })).mutation(async ({ input, ctx }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database not available");
    const [request] = await db7.execute(sql46`
        INSERT INTO signature_requests (documentId, documentType, documentTitle, requestedBy, status, createdAt, updatedAt)
        VALUES (${input.documentId}, 'vault_document', 'Vault Document Signature', ${ctx.user.id}, 'pending', NOW(), NOW())
      `);
    const requestId = request.insertId;
    const [sig] = await db7.execute(sql46`
        INSERT INTO signatures (requestId, signerId, signerName, signerTitle, status, createdAt)
        VALUES (${requestId}, ${ctx.user.id}, ${input.signerName}, ${input.signerTitle || null}, 'pending', NOW())
      `);
    const signatureId = sig.insertId;
    const ipAddress = "127.0.0.1";
    await db7.execute(sql46`
        UPDATE signatures 
        SET signatureType = ${input.signatureType}, 
            signatureData = ${input.signatureData},
            signedAt = NOW(),
            ipAddress = ${ipAddress},
            status = 'signed'
        WHERE id = ${signatureId}
      `);
    await db7.execute(sql46`
        UPDATE signature_requests 
        SET status = 'completed', completedAt = NOW(), updatedAt = NOW()
        WHERE id = ${requestId}
      `);
    await db7.execute(sql46`
        INSERT INTO vault_access_logs (vault_id, document_id, user_id, action, created_at)
        VALUES (1, ${input.documentId}, ${ctx.user.id}, 'sign', NOW())
      `);
    return { success: true, signatureId, message: "Document signed successfully" };
  }),
  // Get vault document signatures
  getDocumentSignatures: protectedProcedure.input(z109.object({ documentId: z109.number() })).query(async ({ input }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database not available");
    const [signatures4] = await db7.execute(sql46`
        SELECT s.*, sr.documentTitle, sr.completedAt
        FROM signatures s
        JOIN signature_requests sr ON s.requestId = sr.id
        WHERE sr.documentId = ${input.documentId}
        ORDER BY s.signedAt DESC
      `);
    return signatures4;
  }),
  // Store user's signature on file
  saveSignatureOnFile: protectedProcedure.input(z109.object({
    signatureType: z109.enum(["typed", "drawn", "uploaded"]),
    signatureData: z109.string()
  })).mutation(async ({ input, ctx }) => {
    const db7 = await getDb();
    if (!db7) throw new Error("Database not available");
    const [member] = await db7.execute(sql46`
        SELECT * FROM board_members WHERE userId = ${ctx.user.id}
      `);
    if (member.length) {
      await db7.execute(sql46`
          UPDATE board_members 
          SET signatureOnFile = ${input.signatureData}, updatedAt = NOW()
          WHERE userId = ${ctx.user.id}
        `);
    }
    return { success: true, message: "Signature saved on file" };
  })
});

