function checkEligibility(age, hasWorkPermit, educationStatus) {
  if (age !== void 0) {
    if (age < 16) return false;
    if (age < 18 && !hasWorkPermit) return false;
  }
  const validEducation = [
    "high_school_diploma",
    "academy_graduate",
    "ged",
    "college_enrolled",
    "college_graduate"
  ];
  return validEducation.includes(educationStatus);
}
function formatLevel(level) {
  const labels = {
    specialist_i: "Specialist I",
    specialist_ii: "Specialist II",
    specialist_iii: "Specialist III",
    associate: "Associate"
  };
  return labels[level] || level;
}
function getTokenBonusForLevel(level) {
  const bonuses = {
    specialist_ii: 100,
    specialist_iii: 250,
    associate: 500
  };
  return bonuses[level] || 0;
}
function calculateAcademyScore(completed, target) {
  if (target === 0) return 10;
  const ratio = Math.min(completed / target, 1.5);
  return Math.round(ratio * 20);
}
function calculateSimulatorScore(sessions, avgScore) {
  const sessionPoints = Math.min(sessions * 2, 10);
  const scorePoints = Math.min(avgScore / 10, 10);
  return Math.round(sessionPoints + scorePoints);
}
function calculateSupervisorScore(attendance, punctuality, initiative, teamwork, quality) {
  return attendance + punctuality + initiative + teamwork + quality;
}
function calculateTokenEconomyScore(earned, spentWisely, savingsRate) {
  let score = 0;
  score += Math.min(earned / 100, 5);
  if (spentWisely) score += 5;
  score += Math.min(savingsRate / 10, 5);
  return Math.round(score);
}
function calculateFiscalScore(budgetAdherence, reportingAccuracy, goalsMet) {
  let score = 0;
  if (budgetAdherence) score += 8;
  score += Math.round(reportingAccuracy / 100 * 6);
  score += Math.min(goalsMet * 2, 6);
  return score;
}
async function getRecommendedLevel(db7, trackId) {
  const tracks = await db7.select().from(specialistTracks).where(eq82(specialistTracks.id, trackId)).limit(1);
  const track = tracks[0];
  if (!track) return null;
  const currentLevel = track.currentLevel;
  const requirements = PROGRESSION_REQUIREMENTS[currentLevel];
  return requirements.nextLevel;
}

