  // ============================================================================
  // AI TOOLS TRACKING
  // ============================================================================
  getAiToolsUsage: publicProcedure.query(async () => {
    const db7 = await getDb();
    if (!db7) return { tools: {}, totalProjects: 0 };
    try {
      const projects2 = await db7.select().from(designProjects);
      const toolUsage = {};
      let projectsWithAi = 0;
      projects2.forEach((p) => {
        if (p.aiToolsUsed) {
          projectsWithAi++;
          const tools = typeof p.aiToolsUsed === "string" ? JSON.parse(p.aiToolsUsed) : p.aiToolsUsed;
          if (Array.isArray(tools)) {
            tools.forEach((tool) => {
              toolUsage[tool] = (toolUsage[tool] || 0) + 1;
            });
          }
        }
      });
      return {
        tools: toolUsage,
        totalProjects: projects2.length,
        projectsWithAi,
        aiAdoptionRate: projects2.length > 0 ? projectsWithAi / projects2.length * 100 : 0
      };
    } catch (error) {
      console.error("Error getting AI tools usage:", error);
      return { tools: {}, totalProjects: 0, projectsWithAi: 0, aiAdoptionRate: 0 };
    }
  }),
