function getAvailableJobs() {
  return [
    {
      name: "signature_expiration_notifications",
      description: "Process and send notifications for signatures expiring within 30 days",
      recommendedSchedule: "0 8 * * *",
      // Daily at 8 AM
      isRunning: isJobRunning("signature_expiration_notifications")
    },
    {
      name: "daily_summary_report",
      description: "Generate daily summary of system activity (new users, signatures, time entries)",
      recommendedSchedule: "0 7 * * *",
      // Daily at 7 AM
      isRunning: isJobRunning("daily_summary_report")
    },
    {
      name: "weekly_compliance_audit",
      description: "Check compliance status across the system (expired signatures, pending timesheets)",
      recommendedSchedule: "0 6 * * 1",
      // Every Monday at 6 AM
      isRunning: isJobRunning("weekly_compliance_audit")
    },
    {
      name: "monthly_data_cleanup",
      description: "Archive old notifications and clean up temporary data",
      recommendedSchedule: "0 3 1 * *",
      // 1st of each month at 3 AM
      isRunning: isJobRunning("monthly_data_cleanup")
    }
  ];
}
async function runJob(jobName, triggeredBy = "manual", triggeredByUserId) {
  switch (jobName) {
    case "signature_expiration_notifications":
      return runSignatureExpirationJob(triggeredBy, triggeredByUserId);
    case "daily_summary_report":
      return runDailySummaryReportJob(triggeredBy, triggeredByUserId);
    case "weekly_compliance_audit":
      return runWeeklyComplianceAuditJob(triggeredBy, triggeredByUserId);
    case "monthly_data_cleanup":
      return runMonthlyDataCleanupJob(triggeredBy, triggeredByUserId);
    default:
      return {
        jobName,
        success: false,
        startedAt: (/* @__PURE__ */ new Date()).toISOString(),
        completedAt: (/* @__PURE__ */ new Date()).toISOString(),
        duration: 0,
        details: {},
        errors: [`Unknown job: ${jobName}`]
      };
  }
}
async function getJobStats() {
  const db7 = await getDb();
  if (!db7) throw new Error("Database not available");
  const [stats] = await db7.select({
    total: sql58`COUNT(*)`,
    successful: sql58`SUM(CASE WHEN status = 'completed' THEN 1 ELSE 0 END)`,
    failed: sql58`SUM(CASE WHEN status = 'failed' THEN 1 ELSE 0 END)`,
    avgDuration: sql58`AVG(duration_ms)`
  }).from(systemJobExecutions);
  const [lastExecution] = await db7.select({ startedAt: systemJobExecutions.startedAt }).from(systemJobExecutions).orderBy(desc71(systemJobExecutions.startedAt)).limit(1);
  return {
    totalExecutions: stats?.total || 0,
    successfulExecutions: stats?.successful || 0,
    failedExecutions: stats?.failed || 0,
    averageDurationMs: stats?.avgDuration || 0,
    lastExecutionTime: lastExecution?.startedAt ? new Date(lastExecution.startedAt) : void 0
  };
}

// server/routers/system-jobs.ts
var systemJobsRouter = router({
  /**
   * Get all available scheduled jobs
   */
  getAvailableJobs: protectedProcedure.query(async () => {
    return getAvailableJobs();
  }),
  /**
   * Get job execution history from database
   */
  getJobHistory: protectedProcedure.input(
    z129.object({
      jobName: z129.string().optional(),
      limit: z129.number().min(1).max(100).default(20)
    }).optional()
  ).query(async ({ input }) => {
    return getJobHistory(input?.jobName, input?.limit);
  }),
  /**
   * Check if a job is currently running
   */
  isJobRunning: protectedProcedure.input(
    z129.object({
      jobName: z129.string()
    })
  ).query(async ({ input }) => {
    return { isRunning: isJobRunning(input.jobName) };
  }),
  /**
   * Get job execution statistics
   */
  getJobStats: protectedProcedure.query(async () => {
    return getJobStats();
  }),
  /**
   * Run a job manually
   */
  runJob: protectedProcedure.input(
    z129.object({
      jobName: z129.string()
    })
  ).mutation(async ({ input, ctx }) => {
    const result = await runJob(input.jobName, "manual", ctx.user?.id);
    return result;
  }),
  /**
   * Run signature expiration notification job
   */
  runSignatureExpirationJob: protectedProcedure.mutation(async ({ ctx }) => {
    const result = await runJob("signature_expiration_notifications", "manual", ctx.user?.id);
    return result;
  }),
  /**
   * Run daily summary report job
   */
  runDailySummaryReport: protectedProcedure.mutation(async ({ ctx }) => {
    const result = await runJob("daily_summary_report", "manual", ctx.user?.id);
    return result;
  }),
  /**
   * Run weekly compliance audit job
   */
  runWeeklyComplianceAudit: protectedProcedure.mutation(async ({ ctx }) => {
    const result = await runJob("weekly_compliance_audit", "manual", ctx.user?.id);
    return result;
  }),
  /**
   * Run monthly data cleanup job
   */
  runMonthlyDataCleanup: protectedProcedure.mutation(async ({ ctx }) => {
    const result = await runJob("monthly_data_cleanup", "manual", ctx.user?.id);
    return result;
  })
});

