function getStartOfDay(date2) {
  const start = new Date(date2);
  start.setHours(0, 0, 0, 0);
  return start;
}
function getEndOfDay(date2) {
  const end = new Date(date2);
  end.setHours(23, 59, 59, 999);
  return end;
}
function getStartOfWeek(date2) {
  const start = new Date(date2);
  const day = start.getDay();
  start.setDate(start.getDate() - day);
  start.setHours(0, 0, 0, 0);
  return start;
}
function getEndOfWeek(date2) {
  const end = new Date(date2);
  const day = end.getDay();
  end.setDate(end.getDate() + (6 - day));
  end.setHours(23, 59, 59, 999);
  return end;
}
function getWeekOfMonth(date2) {
  const firstDay = new Date(date2.getFullYear(), date2.getMonth(), 1);
  return Math.floor((date2.getDate() + firstDay.getDay() - 1) / 7);
}
