// server/routers/auto-diagnostic.ts
init_db();
init_schema();
import { count as count5, eq as eq113, lt as lt4, and as and90 } from "drizzle-orm";
function getOverallStatus(checks) {
  if (checks.some((c) => c.status === "critical")) return "critical";
  if (checks.some((c) => c.status === "warning")) return "warning";
  if (checks.every((c) => c.status === "healthy")) return "healthy";
  return "unknown";
}
var autoDiagnosticRouter = router({
  // Run full system diagnostic
  runDiagnostic: protectedProcedure.query(async ({ ctx }) => {
    const checks = [];
    const recommendations = [];
    const now = /* @__PURE__ */ new Date();
    try {
      const dbCheck = await db.select({ count: count5() }).from(users);
      checks.push({
        category: "Database",
        status: "healthy",
        message: "Database connection active",
        details: { userCount: dbCheck[0]?.count || 0 },
        lastChecked: now
      });
    } catch (error) {
      checks.push({
        category: "Database",
        status: "critical",
        message: "Database connection failed",
        details: { error: String(error) },
        lastChecked: now
      });
      recommendations.push("Check database connection string and server status");
    }
    try {
      const [totalEntities] = await db.select({ count: count5() }).from(businessEntities);
      const [pendingEntities] = await db.select({ count: count5() }).from(businessEntities).where(eq113(businessEntities.status, "pending"));
      const pendingCount = pendingEntities?.count || 0;
      const totalCount = totalEntities?.count || 0;
      let status = "healthy";
      let message = `${totalCount} business entities registered`;
      if (pendingCount > 5) {
        status = "warning";
        message = `${pendingCount} entities pending formation`;
        recommendations.push("Review pending business formations");
      }
      checks.push({
        category: "Business Entities",
        status,
        message,
        details: { total: totalCount, pending: pendingCount },
        lastChecked: now
      });
    } catch (error) {
      checks.push({
        category: "Business Entities",
        status: "unknown",
        message: "Could not check business entities",
        lastChecked: now
      });
    }
    try {
      const [totalHouses] = await db.select({ count: count5() }).from(houses);
      const [activeHouses] = await db.select({ count: count5() }).from(houses).where(eq113(houses.status, "active"));
      checks.push({
        category: "House System",
        status: "healthy",
        message: `${activeHouses?.count || 0} active houses of ${totalHouses?.count || 0} total`,
        details: {
          total: totalHouses?.count || 0,
          active: activeHouses?.count || 0
        },
        lastChecked: now
      });
    } catch (error) {
      checks.push({
        category: "House System",
        status: "unknown",
        message: "Could not check house system",
        lastChecked: now
      });
    }
    try {
      const thirtyDaysFromNow = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1e3);
      const [upcomingDeadlines] = await db.select({ count: count5() }).from(complianceTasks).where(
        and90(
          lt4(complianceTasks.dueDate, thirtyDaysFromNow),
          eq113(complianceTasks.status, "pending")
        )
      );
      const deadlineCount = upcomingDeadlines?.count || 0;
      let status = "healthy";
      let message = "No urgent compliance deadlines";
      if (deadlineCount > 0) {
        status = deadlineCount > 3 ? "warning" : "healthy";
        message = `${deadlineCount} compliance items due within 30 days`;
        if (deadlineCount > 3) {
          recommendations.push("Review upcoming compliance deadlines");
        }
      }
      checks.push({
        category: "Compliance",
        status,
        message,
        details: { upcomingDeadlines: deadlineCount },
        lastChecked: now
      });
    } catch (error) {
      checks.push({
        category: "Compliance",
        status: "unknown",
        message: "Could not check compliance status",
        lastChecked: now
      });
    }
    try {
      checks.push({
        category: "Token Economy",
        status: "healthy",
        message: "Token system operational",
        details: { status: "active" },
        lastChecked: now
      });
    } catch (error) {
      checks.push({
        category: "Token Economy",
        status: "unknown",
        message: "Could not check token economy",
        lastChecked: now
      });
    }
    try {
      const [totalFolders] = await db.select({ count: count5() }).from(documentFolders);
      checks.push({
        category: "Document Storage",
        status: "healthy",
        message: `Document system active with ${totalFolders?.count || 0} folders`,
        details: { totalFolders: totalFolders?.count || 0 },
        lastChecked: now
      });
    } catch (error) {
      checks.push({
        category: "Document Storage",
        status: "unknown",
        message: "Could not check document storage",
        lastChecked: now
      });
    }
    try {
      const [totalUsers] = await db.select({ count: count5() }).from(users);
      checks.push({
        category: "User System",
        status: "healthy",
        message: `${totalUsers?.count || 0} registered users`,
        details: { totalUsers: totalUsers?.count || 0 },
        lastChecked: now
      });
    } catch (error) {
      checks.push({
        category: "User System",
        status: "unknown",
        message: "Could not check user system",
        lastChecked: now
      });
    }
    return {
      overallStatus: getOverallStatus(checks),
      timestamp: now,
      checks,
      recommendations
    };
  }),
  // Get last diagnostic result (cached)
  getLastDiagnostic: publicProcedure.query(async () => {
    return {
      available: false,
      message: "Run a new diagnostic to get current system status"
    };
  }),
  // Get quick health status
  getQuickStatus: publicProcedure.query(async () => {
    try {
      await db.select({ count: count5() }).from(users);
      return {
        status: "operational",
        timestamp: /* @__PURE__ */ new Date(),
        message: "All systems operational"
      };
    } catch (error) {
      return {
        status: "degraded",
        timestamp: /* @__PURE__ */ new Date(),
        message: "Some systems may be experiencing issues"
      };
    }
  }),
  // Trigger manual diagnostic (for admin use)
  triggerManualDiagnostic: protectedProcedure.mutation(async ({ ctx }) => {
    return {
      success: true,
      message: "Diagnostic triggered. Results will be available shortly.",
      triggeredAt: /* @__PURE__ */ new Date(),
      triggeredBy: ctx.user.id
    };
  })
});

// server/routers/investor-management.ts
import { z as z145 } from "zod";
init_db();
import { sql as sql67 } from "drizzle-orm";
import { TRPCError as TRPCError52 } from "@trpc/server";
var MAX_INVESTOR_ALLOCATION_PERCENT = 25;
var NETWORK_POOL_PERCENT = 40;
var HOUSE_RETAINED_PERCENT = 60;
var investorManagementRouter = router({
  // ==========================================
  // SAFEGUARDS
  // ==========================================
  getSafeguards: publicProcedure.query(async () => {
    const db7 = await getDb();
    if (!db7) return [];
    const safeguards = await db7.execute(sql67`
      SELECT * FROM investment_protection_safeguards 
      WHERE isActive = TRUE
      ORDER BY isConstitutional DESC, safeguardType
    `);
    return safeguards[0] || [];
  }),
  getConstitutionalSafeguards: publicProcedure.query(async () => {
    const db7 = await getDb();
    if (!db7) return [];
    const safeguards = await db7.execute(sql67`
      SELECT * FROM investment_protection_safeguards 
      WHERE isConstitutional = TRUE AND isActive = TRUE
    `);
    return safeguards[0] || [];
  }),
  // ==========================================
  // INVESTORS/PARTNERS
  // ==========================================
  getInvestors: protectedProcedure.query(async () => {
    const db7 = await getDb();
    if (!db7) return [];
    const investors = await db7.execute(sql67`
      SELECT * FROM investor_partners ORDER BY createdAt DESC
    `);
    return investors[0] || [];
  }),
  getInvestorById: protectedProcedure.input(z145.object({ id: z145.number() })).query(async ({ input }) => {
    const db7 = await getDb();
    if (!db7) return null;
    const investor = await db7.execute(sql67`
        SELECT * FROM investor_partners WHERE id = ${input.id}
      `);
    return investor[0]?.[0] || null;
  }),
  createInvestor: protectedProcedure.input(z145.object({
    name: z145.string(),
    entityType: z145.enum(["individual", "company", "fund", "family_office", "strategic_partner"]),
    tier: z145.enum(["strategic_partner", "limited_partner", "equity_investor"]),
    contactName: z145.string().optional(),
    contactEmail: z145.string().email().optional(),
    contactPhone: z145.string().optional(),
    address: z145.string().optional(),
    taxId: z145.string().optional(),
    accreditedInvestor: z145.boolean().default(false),
    notes: z145.string().optional()
  })).mutation(async ({ input }) => {
    const db7 = await getDb();
    if (!db7) throw new TRPCError52({ code: "INTERNAL_SERVER_ERROR", message: "Database not available" });
    await db7.execute(sql67`
        INSERT INTO investor_partners 
        (name, entityType, tier, contactName, contactEmail, contactPhone, address, taxId, accreditedInvestor, notes, status)
        VALUES (${input.name}, ${input.entityType}, ${input.tier}, ${input.contactName || null}, 
                ${input.contactEmail || null}, ${input.contactPhone || null}, ${input.address || null},
                ${input.taxId || null}, ${input.accreditedInvestor}, ${input.notes || null}, 'prospect')
      `);
    return { success: true };
  }),
  updateInvestorStatus: protectedProcedure.input(z145.object({
    id: z145.number(),
    status: z145.enum(["prospect", "active", "inactive", "exited"])
  })).mutation(async ({ input }) => {
    const db7 = await getDb();
    if (!db7) throw new TRPCError52({ code: "INTERNAL_SERVER_ERROR", message: "Database not available" });
    await db7.execute(sql67`
        UPDATE investor_partners SET status = ${input.status} WHERE id = ${input.id}
      `);
    return { success: true };
  }),
  // ==========================================
  // OPPORTUNITIES
  // ==========================================
  getOpportunities: protectedProcedure.query(async () => {
    const db7 = await getDb();
    if (!db7) return [];
    const opportunities = await db7.execute(sql67`
      SELECT * FROM investment_opportunities ORDER BY createdAt DESC
    `);
    return opportunities[0] || [];
  }),
  createOpportunity: protectedProcedure.input(z145.object({
    title: z145.string(),
    description: z145.string().optional(),
    opportunityType: z145.enum(["revenue_share", "profit_participation", "equity_stake", "convertible_note", "loan"]),
    targetAmount: z145.number().optional(),
    minimumInvestment: z145.number().optional(),
    maximumInvestment: z145.number().optional(),
    expectedReturn: z145.string().optional(),
    termMonths: z145.number().optional(),
    riskLevel: z145.enum(["low", "medium", "high"]).default("medium"),
    maxPoolAllocation: z145.number().max(MAX_INVESTOR_ALLOCATION_PERCENT).default(25),
    buybackClause: z145.string().optional(),
    sunsetClause: z145.string().optional()
  })).mutation(async ({ ctx, input }) => {
    const db7 = await getDb();
    if (!db7) throw new TRPCError52({ code: "INTERNAL_SERVER_ERROR", message: "Database not available" });
    if (input.maxPoolAllocation > MAX_INVESTOR_ALLOCATION_PERCENT) {
      throw new TRPCError52({
        code: "BAD_REQUEST",
        message: `Maximum allocation cannot exceed ${MAX_INVESTOR_ALLOCATION_PERCENT}% of Network Pool (${MAX_INVESTOR_ALLOCATION_PERCENT * 0.4}% of total)`
      });
    }
    const firewallClause = `Investment is limited to the ${NETWORK_POOL_PERCENT}% Network Pool. The ${HOUSE_RETAINED_PERCENT}% House Retained portion is completely protected and inaccessible to investors.`;
    const vetoRightsClause = "Founding House Chair retains absolute veto power over all investment decisions.";
    await db7.execute(sql67`
        INSERT INTO investment_opportunities 
        (title, description, opportunityType, targetAmount, minimumInvestment, maximumInvestment,
         expectedReturn, termMonths, riskLevel, sourcePool, maxPoolAllocation,
         firewallClause, vetoRightsClause, buybackClause, sunsetClause, status, createdById)
        VALUES (${input.title}, ${input.description || null}, ${input.opportunityType},
                ${input.targetAmount || null}, ${input.minimumInvestment || null}, ${input.maximumInvestment || null},
                ${input.expectedReturn || null}, ${input.termMonths || null}, ${input.riskLevel},
                'network_pool_40', ${input.maxPoolAllocation},
                ${firewallClause}, ${vetoRightsClause}, ${input.buybackClause || null}, ${input.sunsetClause || null},
                'draft', ${ctx.user.id})
      `);
    return { success: true };
  }),
  updateOpportunityStatus: protectedProcedure.input(z145.object({
    id: z145.number(),
    status: z145.enum(["draft", "open", "closed", "funded", "cancelled"])
  })).mutation(async ({ input }) => {
    const db7 = await getDb();
    if (!db7) throw new TRPCError52({ code: "INTERNAL_SERVER_ERROR", message: "Database not available" });
    await db7.execute(sql67`
        UPDATE investment_opportunities SET status = ${input.status} WHERE id = ${input.id}
      `);
    return { success: true };
  }),
  // ==========================================
  // AGREEMENTS
  // ==========================================
  getAgreements: protectedProcedure.query(async () => {
    const db7 = await getDb();
    if (!db7) return [];
    const agreements = await db7.execute(sql67`
      SELECT a.*, i.name as investorName, o.title as opportunityTitle
      FROM investment_agreements a
      LEFT JOIN investor_partners i ON a.investorId = i.id
      LEFT JOIN investment_opportunities o ON a.opportunityId = o.id
      ORDER BY a.createdAt DESC
    `);
    return agreements[0] || [];
  }),
  createAgreement: protectedProcedure.input(z145.object({
    investorId: z145.number(),
    opportunityId: z145.number(),
    investmentAmount: z145.number(),
    ownershipPercentage: z145.number().optional(),
    profitSharePercentage: z145.number().optional(),
    revenueSharePercentage: z145.number().optional(),
    effectiveDate: z145.string(),
    expirationDate: z145.string().optional(),
    buybackTerms: z145.string().optional(),
    buybackPrice: z145.number().optional(),
    sunsetDate: z145.string().optional(),
    sunsetTerms: z145.string().optional()
  })).mutation(async ({ input }) => {
    const db7 = await getDb();
    if (!db7) throw new TRPCError52({ code: "INTERNAL_SERVER_ERROR", message: "Database not available" });
    const currentAllocations = await db7.execute(sql67`
        SELECT SUM(percentageOfPool) as totalAllocated 
        FROM investment_allocations 
        WHERE status = 'active'
      `);
    const totalAllocated = currentAllocations[0]?.[0]?.totalAllocated || 0;
    const newAllocationPercent = input.ownershipPercentage || input.profitSharePercentage || 0;
    if (totalAllocated + newAllocationPercent > MAX_INVESTOR_ALLOCATION_PERCENT) {
      throw new TRPCError52({
        code: "BAD_REQUEST",
        message: `This investment would exceed the maximum ${MAX_INVESTOR_ALLOCATION_PERCENT}% allocation cap. Current: ${totalAllocated}%, Requested: ${newAllocationPercent}%`
      });
    }
    const agreementNumber = `INV-${Date.now()}`;
    await db7.execute(sql67`
        INSERT INTO investment_agreements 
        (investorId, opportunityId, agreementNumber, investmentAmount, ownershipPercentage,
         profitSharePercentage, revenueSharePercentage, effectiveDate, expirationDate,
         buybackTerms, buybackPrice, sunsetDate, sunsetTerms, status)
        VALUES (${input.investorId}, ${input.opportunityId}, ${agreementNumber}, ${input.investmentAmount},
                ${input.ownershipPercentage || null}, ${input.profitSharePercentage || null},
                ${input.revenueSharePercentage || null}, ${input.effectiveDate}, ${input.expirationDate || null},
                ${input.buybackTerms || null}, ${input.buybackPrice || null},
                ${input.sunsetDate || null}, ${input.sunsetTerms || null}, 'draft')
      `);
    return { success: true, agreementNumber };
  }),
  // Execute buyback
  executeBuyback: protectedProcedure.input(z145.object({
    agreementId: z145.number(),
    buybackAmount: z145.number()
  })).mutation(async ({ input }) => {
    const db7 = await getDb();
    if (!db7) throw new TRPCError52({ code: "INTERNAL_SERVER_ERROR", message: "Database not available" });
    await db7.execute(sql67`
        UPDATE investment_agreements 
        SET buybackExercised = TRUE, buybackDate = NOW(), status = 'bought_back'
        WHERE id = ${input.agreementId}
      `);
    await db7.execute(sql67`
        UPDATE investment_allocations 
        SET status = 'terminated'
        WHERE agreementId = ${input.agreementId}
      `);
    return { success: true };
  }),
  // ==========================================
  // ALLOCATIONS & ANALYTICS
  // ==========================================
  getAllocationSummary: protectedProcedure.query(async () => {
    const db7 = await getDb();
    if (!db7) return {
      totalAllocatedPercent: 0,
      remainingCapPercent: MAX_INVESTOR_ALLOCATION_PERCENT,
      networkPoolPercent: NETWORK_POOL_PERCENT,
      houseRetainedPercent: HOUSE_RETAINED_PERCENT,
      activeInvestors: 0,
      totalInvested: 0
    };
    const allocations = await db7.execute(sql67`
      SELECT 
        COALESCE(SUM(percentageOfPool), 0) as totalAllocatedPercent,
        COUNT(DISTINCT investorId) as activeInvestors,
        COALESCE(SUM(allocatedAmount), 0) as totalInvested
      FROM investment_allocations 
      WHERE status = 'active'
    `);
    const data = allocations[0]?.[0] || {};
    return {
      totalAllocatedPercent: Number(data.totalAllocatedPercent) || 0,
      remainingCapPercent: MAX_INVESTOR_ALLOCATION_PERCENT - (Number(data.totalAllocatedPercent) || 0),
      networkPoolPercent: NETWORK_POOL_PERCENT,
      houseRetainedPercent: HOUSE_RETAINED_PERCENT,
      activeInvestors: Number(data.activeInvestors) || 0,
      totalInvested: Number(data.totalInvested) || 0,
      maxAllocationPercent: MAX_INVESTOR_ALLOCATION_PERCENT
    };
  }),
  // Validate investment against safeguards
  validateInvestment: protectedProcedure.input(z145.object({
    investmentAmount: z145.number(),
    allocationPercent: z145.number(),
    investorTier: z145.enum(["strategic_partner", "limited_partner", "equity_investor"])
  })).mutation(async ({ input }) => {
    const db7 = await getDb();
    if (!db7) throw new TRPCError52({ code: "INTERNAL_SERVER_ERROR", message: "Database not available" });
    const violations2 = [];
    const warnings = [];
    const currentAllocations = await db7.execute(sql67`
        SELECT COALESCE(SUM(percentageOfPool), 0) as totalAllocated 
        FROM investment_allocations WHERE status = 'active'
      `);
    const totalAllocated = Number(currentAllocations[0]?.[0]?.totalAllocated) || 0;
    if (totalAllocated + input.allocationPercent > MAX_INVESTOR_ALLOCATION_PERCENT) {
      violations2.push(`Exceeds maximum allocation cap of ${MAX_INVESTOR_ALLOCATION_PERCENT}%`);
    }
    if (input.allocationPercent > 5) {
      warnings.push("Investment exceeds 5% of Network Pool - requires Decision Board approval with 2/3 majority");
    }
    if (input.investorTier === "equity_investor" && input.allocationPercent > 10) {
      warnings.push("Equity investments above 10% require enhanced due diligence");
    }
    return {
      isValid: violations2.length === 0,
      violations: violations2,
      warnings,
      requiresBoardApproval: input.allocationPercent > 5,
      requiresChairApproval: true
      // Always requires Chair approval
    };
  })
});

