function generateQuarterlyPriorities() {
  const allPriorities = [
    { id: "academy", label: "Expand Academy", cost: 8e4, impact: { education: 10 }, description: "Add classrooms and instructors" },
    { id: "wellness", label: "Wellness Services", cost: 6e4, impact: { health: 15 }, description: "Build community health center" },
    { id: "incubator", label: "Business Incubator", cost: 7e4, impact: { jobs: 5 }, description: "Support new member businesses" },
    { id: "housing", label: "Housing Development", cost: 9e4, impact: { population: 25 }, description: "Build affordable housing units" },
    { id: "media", label: "Real-Eye-Nation Studio", cost: 5e4, impact: { influence: 20 }, description: "Expand media production" },
    { id: "agriculture", label: "Community Farm", cost: 45e3, impact: { food: 30 }, description: "Establish sustainable food source" },
    { id: "training", label: "Trade Training Center", cost: 75e3, impact: { skills: 15 }, description: "Vocational training facility" },
    { id: "childcare", label: "Childcare Center", cost: 55e3, impact: { families: 20 }, description: "Support working families" }
  ];
  const shuffled = allPriorities.sort(() => Math.random() - 0.5);
  return shuffled.slice(0, 4 + Math.floor(Math.random() * 2)).map((p) => ({
    ...p,
    votes: [],
    selected: false
  }));
}
function generateServiceContracts() {
  const allContracts = [
    { id: "web-dev", title: "Website Development", budget: 15e3, skills: ["technology"], duration: "3 months" },
    { id: "curriculum", title: "Curriculum Development", budget: 2e4, skills: ["education"], duration: "6 months" },
    { id: "marketing", title: "Marketing Campaign", budget: 1e4, skills: ["media"], duration: "2 months" },
    { id: "legal-review", title: "Legal Document Review", budget: 8e3, skills: ["legal"], duration: "1 month" },
    { id: "accounting", title: "Financial Audit", budget: 12e3, skills: ["finance"], duration: "2 months" },
    { id: "construction", title: "Building Renovation", budget: 5e4, skills: ["construction"], duration: "4 months" },
    { id: "event-planning", title: "Community Event", budget: 5e3, skills: ["coordination"], duration: "1 month" },
    { id: "security", title: "Security Assessment", budget: 7e3, skills: ["security"], duration: "1 month" }
  ];
  const shuffled = allContracts.sort(() => Math.random() - 0.5);
  return shuffled.slice(0, 3 + Math.floor(Math.random() * 2)).map((c) => ({
    ...c,
    bids: [],
    awarded: false
  }));
}
function calculateVoteResult(votingSession) {
  const voteCounts = {};
  votingSession.options.forEach((opt) => {
    voteCounts[opt.id] = 0;
  });
  votingSession.votes.forEach((vote) => {
    voteCounts[vote.optionId] = (voteCounts[vote.optionId] || 0) + 1;
  });
  let maxVotes = 0;
  let winner = votingSession.options[0].id;
  Object.entries(voteCounts).forEach(([optionId, count7]) => {
    if (count7 > maxVotes) {
      maxVotes = count7;
      winner = optionId;
    }
  });
  return winner;
}

