async function sendAlertEmailNotification(alert, recipientEmail) {
  try {
    const template = alert.severity === "critical" ? generateCriticalAlertEmail(alert) : generateWarningAlertEmail(alert);
    const logResult = await db.execute(sql95`
      INSERT INTO notification_logs (
        notification_type, channel, subject, body,
        recipient_email, related_alert_id, status
      ) VALUES (
        'compliance_alert',
        'email',
        ${template.subject},
        ${template.textBody},
        ${recipientEmail || null},
        ${alert.alertId},
        'pending'
      )
    `);
    const sent = await notifyOwner({
      title: template.subject,
      content: template.textBody
    });
    if (sent) {
      await db.execute(sql95`
        UPDATE notification_logs
        SET status = 'sent', sent_at = NOW()
        WHERE related_alert_id = ${alert.alertId}
          AND notification_type = 'compliance_alert'
          AND status = 'pending'
        ORDER BY created_at DESC
        LIMIT 1
      `);
    }
    return { success: sent };
  } catch (error) {
    console.error("[EmailNotifications] Error sending alert email:", error);
    return {
      success: false,
      error: error instanceof Error ? error.message : "Unknown error"
    };
  }
}
