async function getLessonContent(moduleId, lessonId) {
  const module = BUSINESS_SETUP_MODULES.find((m) => m.id === moduleId);
  if (!module) return null;
  return module.lessons.find((l) => l.id === lessonId);
}
async function getModuleQuiz(moduleId) {
  const module = BUSINESS_SETUP_MODULES.find((m) => m.id === moduleId);
  if (!module) return null;
  return module.quiz;
}
async function getOutputDocumentTemplate(moduleId) {
  const module = BUSINESS_SETUP_MODULES.find((m) => m.id === moduleId);
  if (!module) return null;
  return module.outputDocument;
}
async function calculateQuizScore(moduleId, answers) {
  const module = BUSINESS_SETUP_MODULES.find((m) => m.id === moduleId);
  if (!module || !module.quiz) {
    return { score: 0, passed: false, feedback: ["Module not found"] };
  }
  let correct = 0;
  const feedback = [];
  module.quiz.forEach((q, idx) => {
    if (answers[idx] === q.correct) {
      correct++;
      feedback.push(`\u2713 Question ${idx + 1}: Correct!`);
    } else {
      feedback.push(`\u2717 Question ${idx + 1}: ${q.explanation}`);
    }
  });
  const score = Math.round(correct / module.quiz.length * 100);
  const passed = score >= 70;
  return { score, passed, feedback };
}
