// server/routers/simulator-certificates.ts
var simulatorCertificatesRouter = router({
  // Get ordered list of simulators
  getSimulatorOrder: protectedProcedure.query(async () => {
    return getSimulatorOrder();
  }),
  // Get user's simulator progress
  getProgress: protectedProcedure.query(async ({ ctx }) => {
    const completedResults = await db.execute({
      sql: `SELECT DISTINCT certificate_type FROM certificates
            WHERE user_id = ? AND certificate_type IN (
              'business_foundations', 'business_plan', 'grant_writing',
              'financial_management', 'trust_estate', 'contracts_legal',
              'blockchain_crypto', 'entity_operations', 'insurance_planning'
            )`,
      args: [ctx.user.id]
    });
    const typeToKey = {
      business_foundations: "business",
      business_plan: "business-plan",
      grant_writing: "grant",
      financial_management: "financial",
      trust_estate: "trust",
      contracts_legal: "contracts",
      blockchain_crypto: "blockchain",
      entity_operations: "operations",
      insurance_planning: "insurance"
    };
    const completedSimulators = completedResults.rows.map(
      (row) => typeToKey[row.certificate_type] || row.certificate_type
    );
    return calculateSimulatorProgress(completedSimulators);
  }),
  // Check if user can access a simulator
  checkAccess: protectedProcedure.input(z199.object({ simulatorKey: z199.string() })).query(async ({ ctx, input }) => {
    const completedResults = await db.execute({
      sql: `SELECT DISTINCT certificate_type FROM certificates
              WHERE user_id = ? AND certificate_type IN (
                'business_foundations', 'business_plan', 'grant_writing',
                'financial_management', 'trust_estate', 'contracts_legal',
                'blockchain_crypto', 'entity_operations', 'insurance_planning'
              )`,
      args: [ctx.user.id]
    });
    const typeToKey = {
      business_foundations: "business",
      business_plan: "business-plan",
      grant_writing: "grant",
      financial_management: "financial",
      trust_estate: "trust",
      contracts_legal: "contracts",
      blockchain_crypto: "blockchain",
      entity_operations: "operations",
      insurance_planning: "insurance"
    };
    const completedSimulators = completedResults.rows.map(
      (row) => typeToKey[row.certificate_type] || row.certificate_type
    );
    return checkPrerequisites(input.simulatorKey, completedSimulators);
  }),
  // Issue certificate for completed simulator
  issueCertificate: protectedProcedure.input(z199.object({ simulatorKey: z199.string() })).mutation(async ({ ctx, input }) => {
    const simulator = getSimulatorByKey(input.simulatorKey);
    if (!simulator) {
      throw new Error("Invalid simulator");
    }
    const existingCert = await db.execute({
      sql: `SELECT id FROM certificates
              WHERE user_id = ? AND certificate_type = ?`,
      args: [ctx.user.id, simulator.certificateType]
    });
    if (existingCert.rows.length > 0) {
      return {
        success: true,
        message: "Certificate already issued",
        certificateId: existingCert.rows[0].id,
        alreadyIssued: true
      };
    }
    const certData = generateCertificateData(
      ctx.user.id,
      ctx.user.name || "Student",
      input.simulatorKey
    );
    if (!certData) {
      throw new Error("Failed to generate certificate data");
    }
    const blockchainData = generateBlockchainRecordData({
      userId: ctx.user.id,
      certificateType: certData.certificateType,
      title: certData.title,
      issuedAt: certData.issuedAt
    });
    const lastBlock = await db.execute({
      sql: `SELECT MAX(block_number) as last_block FROM blockchain_records`
    });
    const nextBlockNumber = (lastBlock.rows[0]?.last_block || 0) + 1;
    await db.execute({
      sql: `INSERT INTO blockchain_records (block_number, hash, data, record_type, entity_id, created_at)
              VALUES (?, ?, ?, 'certificate', ?, NOW())`,
      args: [nextBlockNumber, blockchainData.hash, blockchainData.data, ctx.user.id]
    });
    const certResult = await db.execute({
      sql: `INSERT INTO certificates (user_id, certificate_type, title, description, blockchain_hash, block_number, issued_at)
              VALUES (?, ?, ?, ?, ?, ?, NOW())`,
      args: [
        ctx.user.id,
        certData.certificateType,
        certData.title,
        certData.description,
        blockchainData.hash,
        nextBlockNumber
      ]
    });
    await db.execute({
      sql: `INSERT INTO token_transactions (user_id, amount, type, description, created_at)
              VALUES (?, ?, 'earned', ?, NOW())`,
      args: [ctx.user.id, simulator.tokensReward, `Completed ${simulator.title} Simulator`]
    });
    await db.execute({
      sql: `UPDATE users SET token_balance = COALESCE(token_balance, 0) + ? WHERE id = ?`,
      args: [simulator.tokensReward, ctx.user.id]
    });
    return {
      success: true,
      message: `Certificate issued! You earned ${simulator.tokensReward} tokens.`,
      certificateId: certResult.insertId,
      blockchainHash: blockchainData.hash,
      blockNumber: nextBlockNumber,
      tokensAwarded: simulator.tokensReward
    };
  }),
  // Get user's certificates
  getCertificates: protectedProcedure.query(async ({ ctx }) => {
    const results = await db.execute({
      sql: `SELECT id, certificate_type, title, description, blockchain_hash, block_number, issued_at
            FROM certificates
            WHERE user_id = ?
            ORDER BY issued_at DESC`,
      args: [ctx.user.id]
    });
    return results.rows.map((row) => ({
      id: row.id,
      certificateType: row.certificate_type,
      title: row.title,
      description: row.description,
      blockchainHash: row.blockchain_hash,
      blockNumber: row.block_number,
      issuedAt: row.issued_at,
      displayInfo: getCertificateDisplayInfo(row.certificate_type)
    }));
  }),
  // Get single certificate details
  getCertificate: protectedProcedure.input(z199.object({ certificateId: z199.number() })).query(async ({ ctx, input }) => {
    const result = await db.execute({
      sql: `SELECT c.*, u.name as user_name
              FROM certificates c
              JOIN users u ON c.user_id = u.id
              WHERE c.id = ? AND c.user_id = ?`,
      args: [input.certificateId, ctx.user.id]
    });
    if (result.rows.length === 0) {
      return null;
    }
    const cert = result.rows[0];
    return {
      id: cert.id,
      certificateType: cert.certificate_type,
      title: cert.title,
      description: cert.description,
      blockchainHash: cert.blockchain_hash,
      blockNumber: cert.block_number,
      issuedAt: cert.issued_at,
      userName: cert.user_name,
      displayInfo: getCertificateDisplayInfo(cert.certificate_type)
    };
  }),
  // Get certificate HTML for download/print
  getCertificateHtml: protectedProcedure.input(z199.object({ certificateId: z199.number() })).query(async ({ ctx, input }) => {
    const result = await db.execute({
      sql: `SELECT c.*, u.name as user_name
              FROM certificates c
              JOIN users u ON c.user_id = u.id
              WHERE c.id = ? AND c.user_id = ?`,
      args: [input.certificateId, ctx.user.id]
    });
    if (result.rows.length === 0) {
      throw new Error("Certificate not found");
    }
    const cert = result.rows[0];
    const displayInfo = getCertificateDisplayInfo(cert.certificate_type);
    return getCertificateTemplate(
      cert.user_name,
      cert.title,
      displayInfo?.title || cert.title,
      new Date(cert.issued_at),
      cert.blockchain_hash
    );
  }),
  // Verify certificate on blockchain
  verifyCertificate: protectedProcedure.input(z199.object({ blockchainHash: z199.string() })).query(async ({ input }) => {
    const result = await db.execute({
      sql: `SELECT br.*, c.title, c.certificate_type, u.name as user_name
              FROM blockchain_records br
              LEFT JOIN certificates c ON br.hash = c.blockchain_hash
              LEFT JOIN users u ON c.user_id = u.id
              WHERE br.hash = ?`,
      args: [input.blockchainHash]
    });
    if (result.rows.length === 0) {
      return { verified: false, message: "Certificate not found on blockchain" };
    }
    const record = result.rows[0];
    return {
      verified: true,
      message: "Certificate verified on LuvLedger blockchain",
      certificate: {
        title: record.title,
        certificateType: record.certificate_type,
        userName: record.user_name,
        blockNumber: record.block_number,
        timestamp: record.created_at
      }
    };
  }),
  // Get all certificates for profile display
  getProfileCertificates: protectedProcedure.query(async ({ ctx }) => {
    const results = await db.execute({
      sql: `SELECT certificate_type, title, issued_at, blockchain_hash
            FROM certificates
            WHERE user_id = ?
            ORDER BY issued_at DESC`,
      args: [ctx.user.id]
    });
    const certificates4 = results.rows.map((row) => ({
      certificateType: row.certificate_type,
      title: row.title,
      issuedAt: row.issued_at,
      blockchainHash: row.blockchain_hash,
      displayInfo: getCertificateDisplayInfo(row.certificate_type)
    }));
    const totalCertificates = certificates4.length;
    const totalPossible = 9;
    return {
      certificates: certificates4,
      totalCertificates,
      totalPossible,
      progressPercent: Math.round(totalCertificates / totalPossible * 100)
    };
  })
});

// server/routers/token-registry.ts
import { z as z200 } from "zod";
init_db();

// server/services/token-registry.ts
var TOKEN_TYPES = {
  MIRROR: "mirror",
  SPARK_OF_KNOWING: "spark_of_knowing",
  HOUSE_ACTIVATION: "house_activation",
  GIFT: "gift",
  CROWN: "crown"
};
var MIRROR_TOKEN_LOCK_WEEKS = 39;
var MIRROR_TOKEN_LOCK_MS = MIRROR_TOKEN_LOCK_WEEKS * 7 * 24 * 60 * 60 * 1e3;
var SUCCESSION_INTERIM_DAYS = 40;
var SUCCESSION_CONFIRMATIONS_REQUIRED = 3;
var AMENDMENT_MAJORITY_PERCENT = 60;
function isMirrorTokenLocked(lockedUntil) {
  return /* @__PURE__ */ new Date() < lockedUntil;
}
function calculateMirrorTokenLockEnd(createdAt = /* @__PURE__ */ new Date()) {
  return new Date(createdAt.getTime() + MIRROR_TOKEN_LOCK_MS);
}
function getRemainingLockWeeks(lockedUntil) {
  const now = /* @__PURE__ */ new Date();
  if (now >= lockedUntil) return 0;
  const remainingMs = lockedUntil.getTime() - now.getTime();
  return Math.ceil(remainingMs / (7 * 24 * 60 * 60 * 1e3));
}
function createMirrorTokenData(houseId, holderId, amount, transferredFrom) {
  const now = /* @__PURE__ */ new Date();
  const lockedUntil = calculateMirrorTokenLockEnd(now);
  return {
    houseId,
    holderId,
    amount,
    lockedUntil,
    isLocked: true,
    createdAt: now,
    transferredFrom
  };
}
function createSparkOfKnowingData(recipientId, grantedBy, reason) {
  return {
    type: "spark_of_knowing",
    recipientId,
    grantedBy,
    reason,
    createdAt: /* @__PURE__ */ new Date(),
    isActive: true
  };
}
function createHouseActivationData(recipientId, houseId, grantedBy, reason) {
  return {
    type: "house_activation",
    recipientId,
    houseId,
    grantedBy,
    reason,
    createdAt: /* @__PURE__ */ new Date(),
    isActive: false
    // Requires activation
  };
}
function calculateInterimEndDate(startDate = /* @__PURE__ */ new Date()) {
  const endDate = new Date(startDate);
  endDate.setDate(endDate.getDate() + SUCCESSION_INTERIM_DAYS);
  return endDate;
}
function createSuccessionRecordData(houseId, previousHolderId, newHolderId) {
  const now = /* @__PURE__ */ new Date();
  return {
    houseId,
    previousHolderId,
    newHolderId,
    interimStartDate: now,
    interimEndDate: calculateInterimEndDate(now),
    confirmations: [],
    status: "pending"
  };
}
function calculateAmendmentResults(votes2) {
  const approveCount = votes2.filter((v) => v.vote === "approve").length;
  const rejectCount = votes2.filter((v) => v.vote === "reject").length;
  const abstainCount = votes2.filter((v) => v.vote === "abstain").length;
  const totalVotes = approveCount + rejectCount;
  const approvePercent = totalVotes > 0 ? Math.round(approveCount / totalVotes * 100) : 0;
  const passed = approvePercent >= AMENDMENT_MAJORITY_PERCENT;
  return {
    approveCount,
    rejectCount,
    abstainCount,
    totalVotes,
    approvePercent,
    passed
  };
}
function createAmendmentData(title, description, proposedBy, votingDurationDays = 14) {
  const now = /* @__PURE__ */ new Date();
  const votingEndsAt = new Date(now);
  votingEndsAt.setDate(votingEndsAt.getDate() + votingDurationDays);
  return {
    title,
    description,
    proposedBy,
    proposedAt: now,
    votingEndsAt,
    votes: [],
    status: "voting",
    requiredMajority: AMENDMENT_MAJORITY_PERCENT
  };
}
function getTokenRegistrySummary() {
  return {
    tokenTypes: Object.values(TOKEN_TYPES),
    mirrorTokenLockWeeks: MIRROR_TOKEN_LOCK_WEEKS,
    successionInterimDays: SUCCESSION_INTERIM_DAYS,
    successionConfirmationsRequired: SUCCESSION_CONFIRMATIONS_REQUIRED,
    amendmentMajorityPercent: AMENDMENT_MAJORITY_PERCENT
  };
}

// server/routers/token-registry.ts
var tokenRegistryRouter = router({
  // Get registry summary
  getSummary: protectedProcedure.query(async () => {
    return getTokenRegistrySummary();
  }),
  // === MIRROR TOKENS ===
  // Issue Mirror Token
  issueMirrorToken: protectedProcedure.input(z200.object({
    houseId: z200.number(),
    holderId: z200.number(),
    amount: z200.number().min(1),
    transferredFrom: z200.number().optional()
  })).mutation(async ({ ctx, input }) => {
    const tokenData = createMirrorTokenData(
      input.houseId,
      input.holderId,
      input.amount,
      input.transferredFrom
    );
    const result = await db.execute({
      sql: `INSERT INTO mirror_tokens (house_id, holder_id, amount, locked_until, is_locked, created_at, transferred_from)
              VALUES (?, ?, ?, ?, ?, ?, ?)`,
      args: [
        tokenData.houseId,
        tokenData.holderId,
        tokenData.amount,
        tokenData.lockedUntil.toISOString(),
        tokenData.isLocked ? 1 : 0,
        tokenData.createdAt.toISOString(),
        tokenData.transferredFrom || null
      ]
    });
    await db.execute({
      sql: `INSERT INTO blockchain_records (block_number, hash, data, record_type, entity_id, created_at)
              VALUES ((SELECT COALESCE(MAX(block_number), 0) + 1 FROM blockchain_records br2),
                      ?, ?, 'mirror_token', ?, NOW())`,
      args: [
        `0x${Buffer.from(JSON.stringify({ type: "MIRROR_TOKEN_ISSUED", ...tokenData })).toString("hex").slice(0, 64)}`,
        JSON.stringify({ type: "MIRROR_TOKEN_ISSUED", ...tokenData }),
        input.holderId
      ]
    });
    return {
      success: true,
      tokenId: result.insertId,
      lockedUntil: tokenData.lockedUntil,
      lockWeeks: MIRROR_TOKEN_LOCK_WEEKS
    };
  }),
  // Get Mirror Tokens for house
  getMirrorTokens: protectedProcedure.input(z200.object({ houseId: z200.number() })).query(async ({ input }) => {
    const results = await db.execute({
      sql: `SELECT mt.*, u.name as holder_name
              FROM mirror_tokens mt
              LEFT JOIN users u ON mt.holder_id = u.id
              WHERE mt.house_id = ?
              ORDER BY mt.created_at DESC`,
      args: [input.houseId]
    });
    return results.rows.map((row) => ({
      id: row.id,
      houseId: row.house_id,
      holderId: row.holder_id,
      holderName: row.holder_name,
      amount: row.amount,
      lockedUntil: new Date(row.locked_until),
      isLocked: isMirrorTokenLocked(new Date(row.locked_until)),
      remainingLockWeeks: getRemainingLockWeeks(new Date(row.locked_until)),
      createdAt: row.created_at,
      transferredFrom: row.transferred_from
    }));
  }),
  // Check Mirror Token lock status
  checkMirrorTokenLock: protectedProcedure.input(z200.object({ tokenId: z200.number() })).query(async ({ input }) => {
    const result = await db.execute({
      sql: `SELECT locked_until FROM mirror_tokens WHERE id = ?`,
      args: [input.tokenId]
    });
    if (result.rows.length === 0) {
      return { exists: false };
    }
    const lockedUntil = new Date(result.rows[0].locked_until);
    return {
      exists: true,
      isLocked: isMirrorTokenLocked(lockedUntil),
      lockedUntil,
      remainingWeeks: getRemainingLockWeeks(lockedUntil)
    };
  }),
  // === SPARK TOKENS ===
  // Issue Spark of Knowing
  issueSparkOfKnowing: protectedProcedure.input(z200.object({
    recipientId: z200.number(),
    reason: z200.string().min(1)
  })).mutation(async ({ ctx, input }) => {
    const tokenData = createSparkOfKnowingData(
      input.recipientId,
      ctx.user.id,
      input.reason
    );
    const result = await db.execute({
      sql: `INSERT INTO spark_tokens (type, recipient_id, granted_by, reason, created_at, is_active)
              VALUES (?, ?, ?, ?, ?, ?)`,
      args: [
        tokenData.type,
        tokenData.recipientId,
        tokenData.grantedBy,
        tokenData.reason,
        tokenData.createdAt.toISOString(),
        tokenData.isActive ? 1 : 0
      ]
    });
    return {
      success: true,
      tokenId: result.insertId,
      type: "spark_of_knowing"
    };
  }),
  // Issue House Activation Token
  issueHouseActivation: protectedProcedure.input(z200.object({
    recipientId: z200.number(),
    houseId: z200.number(),
    reason: z200.string().min(1)
  })).mutation(async ({ ctx, input }) => {
    const tokenData = createHouseActivationData(
      input.recipientId,
      input.houseId,
      ctx.user.id,
      input.reason
    );
    const result = await db.execute({
      sql: `INSERT INTO spark_tokens (type, recipient_id, house_id, granted_by, reason, created_at, is_active)
              VALUES (?, ?, ?, ?, ?, ?, ?)`,
      args: [
        tokenData.type,
        tokenData.recipientId,
        tokenData.houseId,
        tokenData.grantedBy,
        tokenData.reason,
        tokenData.createdAt.toISOString(),
        tokenData.isActive ? 1 : 0
      ]
    });
    return {
      success: true,
      tokenId: result.insertId,
      type: "house_activation"
    };
  }),
  // Activate House Activation Token
  activateHouseToken: protectedProcedure.input(z200.object({ tokenId: z200.number() })).mutation(async ({ ctx, input }) => {
    const result = await db.execute({
      sql: `UPDATE spark_tokens SET is_active = 1, activated_at = NOW()
              WHERE id = ? AND recipient_id = ? AND type = 'house_activation' AND is_active = 0`,
      args: [input.tokenId, ctx.user.id]
    });
    if (result.rowsAffected === 0) {
      throw new Error("Token not found or already activated");
    }
    return { success: true, message: "House activation token activated" };
  }),
  // Get user's Spark Tokens
  getSparkTokens: protectedProcedure.query(async ({ ctx }) => {
    const results = await db.execute({
      sql: `SELECT st.*, u.name as granter_name
            FROM spark_tokens st
            LEFT JOIN users u ON st.granted_by = u.id
            WHERE st.recipient_id = ?
            ORDER BY st.created_at DESC`,
      args: [ctx.user.id]
    });
    return results.rows.map((row) => ({
      id: row.id,
      type: row.type,
      houseId: row.house_id,
      grantedBy: row.granted_by,
      granterName: row.granter_name,
      reason: row.reason,
      createdAt: row.created_at,
      activatedAt: row.activated_at,
      isActive: row.is_active === 1
    }));
  }),
  // === SUCCESSION PROTOCOL ===
  // Initiate succession
  initiateSuccession: protectedProcedure.input(z200.object({
    houseId: z200.number(),
    newHolderId: z200.number()
  })).mutation(async ({ ctx, input }) => {
    const recordData = createSuccessionRecordData(
      input.houseId,
      ctx.user.id,
      input.newHolderId
    );
    const result = await db.execute({
      sql: `INSERT INTO succession_records (house_id, previous_holder_id, new_holder_id, 
              interim_start_date, interim_end_date, status, created_at)
              VALUES (?, ?, ?, ?, ?, ?, NOW())`,
      args: [
        recordData.houseId,
        recordData.previousHolderId,
        recordData.newHolderId,
        recordData.interimStartDate.toISOString(),
        recordData.interimEndDate.toISOString(),
        recordData.status
      ]
    });
    return {
      success: true,
      successionId: result.insertId,
      interimEndDate: recordData.interimEndDate,
      interimDays: SUCCESSION_INTERIM_DAYS,
      confirmationsRequired: SUCCESSION_CONFIRMATIONS_REQUIRED
    };
  }),
  // Add succession confirmation
  confirmSuccession: protectedProcedure.input(z200.object({
    successionId: z200.number(),
    vote: z200.enum(["approve", "reject"]),
    reason: z200.string().optional()
  })).mutation(async ({ ctx, input }) => {
    const existingCheck = await db.execute({
      sql: `SELECT id FROM succession_confirmations WHERE succession_id = ? AND confirmer_id = ?`,
      args: [input.successionId, ctx.user.id]
    });
    if (existingCheck.rows.length > 0) {
      throw new Error("You have already voted on this succession");
    }
    await db.execute({
      sql: `INSERT INTO succession_confirmations (succession_id, confirmer_id, confirmer_name, vote, reason, confirmed_at)
              VALUES (?, ?, ?, ?, ?, NOW())`,
      args: [input.successionId, ctx.user.id, ctx.user.name, input.vote, input.reason || null]
    });
    const confirmations = await db.execute({
      sql: `SELECT vote FROM succession_confirmations WHERE succession_id = ?`,
      args: [input.successionId]
    });
    const approvals2 = confirmations.rows.filter((r) => r.vote === "approve").length;
    const rejections = confirmations.rows.filter((r) => r.vote === "reject").length;
    let newStatus = "pending";
    if (approvals2 >= SUCCESSION_CONFIRMATIONS_REQUIRED) {
      newStatus = "confirmed";
    } else if (rejections >= SUCCESSION_CONFIRMATIONS_REQUIRED) {
      newStatus = "rejected";
    }
    if (newStatus !== "pending") {
      await db.execute({
        sql: `UPDATE succession_records SET status = ?, completed_at = NOW() WHERE id = ?`,
        args: [newStatus, input.successionId]
      });
    }
    return {
      success: true,
      currentApprovals: approvals2,
      currentRejections: rejections,
      status: newStatus,
      confirmationsRequired: SUCCESSION_CONFIRMATIONS_REQUIRED
    };
  }),
  // Get succession records for house
  getSuccessionRecords: protectedProcedure.input(z200.object({ houseId: z200.number() })).query(async ({ input }) => {
    const results = await db.execute({
      sql: `SELECT sr.*, 
              prev.name as previous_holder_name,
              new.name as new_holder_name
              FROM succession_records sr
              LEFT JOIN users prev ON sr.previous_holder_id = prev.id
              LEFT JOIN users new ON sr.new_holder_id = new.id
              WHERE sr.house_id = ?
              ORDER BY sr.created_at DESC`,
      args: [input.houseId]
    });
    const records = [];
    for (const row of results.rows) {
      const confirmations = await db.execute({
        sql: `SELECT * FROM succession_confirmations WHERE succession_id = ?`,
        args: [row.id]
      });
      records.push({
        id: row.id,
        houseId: row.house_id,
        previousHolderId: row.previous_holder_id,
        previousHolderName: row.previous_holder_name,
        newHolderId: row.new_holder_id,
        newHolderName: row.new_holder_name,
        interimStartDate: row.interim_start_date,
        interimEndDate: row.interim_end_date,
        status: row.status,
        completedAt: row.completed_at,
        confirmations: confirmations.rows.map((c) => ({
          confirmerId: c.confirmer_id,
          confirmerName: c.confirmer_name,
          vote: c.vote,
          reason: c.reason,
          confirmedAt: c.confirmed_at
        }))
      });
    }
    return records;
  }),
  // === AMENDMENTS ===
  // Propose amendment
  proposeAmendment: protectedProcedure.input(z200.object({
    title: z200.string().min(1),
    description: z200.string().min(1),
    votingDurationDays: z200.number().min(7).max(30).default(14)
  })).mutation(async ({ ctx, input }) => {
    const amendmentData = createAmendmentData(
      input.title,
      input.description,
      ctx.user.id,
      input.votingDurationDays
    );
    const result = await db.execute({
      sql: `INSERT INTO amendments (title, description, proposed_by, proposed_at, voting_ends_at, status, required_majority)
              VALUES (?, ?, ?, ?, ?, ?, ?)`,
      args: [
        amendmentData.title,
        amendmentData.description,
        amendmentData.proposedBy,
        amendmentData.proposedAt.toISOString(),
        amendmentData.votingEndsAt.toISOString(),
        amendmentData.status,
        amendmentData.requiredMajority
      ]
    });
    return {
      success: true,
      amendmentId: result.insertId,
      votingEndsAt: amendmentData.votingEndsAt,
      requiredMajority: AMENDMENT_MAJORITY_PERCENT
    };
  }),
  // Vote on amendment
  voteOnAmendment: protectedProcedure.input(z200.object({
    amendmentId: z200.number(),
    vote: z200.enum(["approve", "reject", "abstain"]),
    reason: z200.string().optional()
  })).mutation(async ({ ctx, input }) => {
    const existingVote = await db.execute({
      sql: `SELECT id FROM amendment_votes WHERE amendment_id = ? AND voter_id = ?`,
      args: [input.amendmentId, ctx.user.id]
    });
    if (existingVote.rows.length > 0) {
      throw new Error("You have already voted on this amendment");
    }
    const amendment = await db.execute({
      sql: `SELECT voting_ends_at, status FROM amendments WHERE id = ?`,
      args: [input.amendmentId]
    });
    if (amendment.rows.length === 0) {
      throw new Error("Amendment not found");
    }
    const amendmentRow = amendment.rows[0];
    if (amendmentRow.status !== "voting") {
      throw new Error("Voting has ended for this amendment");
    }
    if (/* @__PURE__ */ new Date() > new Date(amendmentRow.voting_ends_at)) {
      throw new Error("Voting period has expired");
    }
    await db.execute({
      sql: `INSERT INTO amendment_votes (amendment_id, voter_id, voter_name, vote, reason, voted_at)
              VALUES (?, ?, ?, ?, ?, NOW())`,
      args: [input.amendmentId, ctx.user.id, ctx.user.name, input.vote, input.reason || null]
    });
    return { success: true, message: "Vote recorded" };
  }),
  // Get amendments
  getAmendments: protectedProcedure.input(z200.object({
    status: z200.enum(["voting", "passed", "rejected", "expired", "all"]).default("all")
  })).query(async ({ input }) => {
    let sql113 = `SELECT a.*, u.name as proposer_name FROM amendments a
                 LEFT JOIN users u ON a.proposed_by = u.id`;
    const args = [];
    if (input.status !== "all") {
      sql113 += ` WHERE a.status = ?`;
      args.push(input.status);
    }
    sql113 += ` ORDER BY a.proposed_at DESC`;
    const results = await db.execute({ sql: sql113, args });
    const amendments = [];
    for (const row of results.rows) {
      const votes2 = await db.execute({
        sql: `SELECT * FROM amendment_votes WHERE amendment_id = ?`,
        args: [row.id]
      });
      const voteResults = calculateAmendmentResults(votes2.rows);
      amendments.push({
        id: row.id,
        title: row.title,
        description: row.description,
        proposedBy: row.proposed_by,
        proposerName: row.proposer_name,
        proposedAt: row.proposed_at,
        votingEndsAt: row.voting_ends_at,
        status: row.status,
        requiredMajority: row.required_majority,
        votes: votes2.rows.map((v) => ({
          voterId: v.voter_id,
          voterName: v.voter_name,
          vote: v.vote,
          reason: v.reason,
          votedAt: v.voted_at
        })),
        results: voteResults
      });
    }
    return amendments;
  }),
  // Finalize amendment (admin only)
  finalizeAmendment: protectedProcedure.input(z200.object({ amendmentId: z200.number() })).mutation(async ({ input }) => {
    const amendment = await db.execute({
      sql: `SELECT * FROM amendments WHERE id = ?`,
      args: [input.amendmentId]
    });
    if (amendment.rows.length === 0) {
      throw new Error("Amendment not found");
    }
    const amendmentRow = amendment.rows[0];
    if (/* @__PURE__ */ new Date() < new Date(amendmentRow.voting_ends_at)) {
      throw new Error("Voting period has not ended");
    }
    const votes2 = await db.execute({
      sql: `SELECT vote FROM amendment_votes WHERE amendment_id = ?`,
      args: [input.amendmentId]
    });
    const results = calculateAmendmentResults(votes2.rows);
    const newStatus = results.passed ? "passed" : "rejected";
    await db.execute({
      sql: `UPDATE amendments SET status = ? WHERE id = ?`,
      args: [newStatus, input.amendmentId]
    });
    return {
      success: true,
      status: newStatus,
      results
    };
  })
});

