// server/services/foundation-layer-build.ts
function calculateMetricStatus(current, target) {
  const percentage = current / target * 100;
  if (percentage >= 90) return "on_track";
  if (percentage >= 70) return "at_risk";
  return "off_track";
}
function createMEMetricData(name, category, targetValue, unit, frequency) {
  return {
    name,
    category,
    targetValue,
    currentValue: 0,
    unit,
    frequency,
    lastUpdated: /* @__PURE__ */ new Date(),
    trend: "stable",
    status: "on_track"
  };
}
function generateMEReportSummary(metrics2) {
  const onTrack = metrics2.filter((m) => m.status === "on_track").length;
  const atRisk = metrics2.filter((m) => m.status === "at_risk").length;
  const offTrack = metrics2.filter((m) => m.status === "off_track").length;
  let overallHealth = "healthy";
  if (offTrack > metrics2.length * 0.3) overallHealth = "critical";
  else if (atRisk > metrics2.length * 0.3) overallHealth = "warning";
  return {
    totalMetrics: metrics2.length,
    onTrack,
    atRisk,
    offTrack,
    overallHealth
  };
}
function calculateRiskScore(likelihood, impact) {
  return likelihood * impact;
}
function getRiskLevel(score) {
  if (score <= 4) return "low";
  if (score <= 9) return "medium";
  if (score <= 16) return "high";
  return "critical";
}
function createRiskData(title, description, category, likelihood, impact, owner) {
  return {
    title,
    description,
    category,
    likelihood,
    impact,
    riskScore: calculateRiskScore(likelihood, impact),
    status: "identified",
    owner,
    mitigationPlan: "",
    contingencyPlan: "",
    reviewDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1e3),
    // 30 days
    createdAt: /* @__PURE__ */ new Date()
  };
}
function getRiskMatrix() {
  const matrix = [];
  for (let l = 1; l <= 5; l++) {
    for (let i = 1; i <= 5; i++) {
      matrix.push({
        likelihood: l,
        impact: i,
        level: getRiskLevel(l * i)
      });
    }
  }
  return matrix;
}
function createFacilityData(name, type, address, city, state, zipCode, squareFootage, ownershipType, value, annualCost) {
  return {
    name,
    type,
    address,
    city,
    state,
    zipCode,
    country: "USA",
    squareFootage,
    ownershipType,
    status: "active",
    acquiredDate: /* @__PURE__ */ new Date(),
    value,
    annualCost
  };
}
function createLandParcelData(parcelId, name, acreage, zoning, address, county, state, ownershipType, purchasePrice) {
  return {
    parcelId,
    name,
    acreage,
    zoning,
    address,
    county,
    state,
    ownershipType,
    acquiredDate: /* @__PURE__ */ new Date(),
    purchasePrice,
    currentValue: purchasePrice,
    taxAssessment: purchasePrice * 0.8,
    annualTaxes: purchasePrice * 0.8 * 0.015,
    // Estimated 1.5% tax rate
    encumbrances: [],
    status: "active"
  };
}
function getFoundationLayerSummary() {
  return {
    modules: ["Monitoring & Evaluation", "Risk & Contingency", "Facilities & Land Registry"],
    meCategories: ["output", "outcome", "impact"],
    meFrequencies: ["daily", "weekly", "monthly", "quarterly", "annual"],
    riskCategories: ["strategic", "operational", "financial", "compliance", "reputational"],
    riskLevels: ["low", "medium", "high", "critical"],
    facilityTypes: ["office", "warehouse", "production", "retail", "residential", "land"],
    ownershipTypes: ["owned", "leased", "managed", "fee_simple", "leasehold", "easement", "trust"]
  };
}

