function getContractTemplatesByCategory(category) {
  return getAllContractTemplates().filter((t2) => t2.category === category);
}
function validateContractData(template, data) {
  const errors = [];
  for (const field of template.customizableFields) {
    const value = data[field.name];
    if (field.required && (value === void 0 || value === null || value === "")) {
      errors.push(`${field.label} is required`);
      continue;
    }
    if (!value) continue;
    if (field.type === "number" && field.validation) {
      const numValue = Number(value);
      if (field.validation.min !== void 0 && numValue < field.validation.min) {
        errors.push(`${field.label} must be at least ${field.validation.min}`);
      }
      if (field.validation.max !== void 0 && numValue > field.validation.max) {
        errors.push(`${field.label} must be no more than ${field.validation.max}`);
      }
    }
    if (field.type === "text" && field.validation?.maxLength) {
      if (String(value).length > field.validation.maxLength) {
        errors.push(`${field.label} must be no more than ${field.validation.maxLength} characters`);
      }
    }
    if (field.type === "select" && field.options) {
      if (!field.options.includes(value)) {
        errors.push(`${field.label} must be one of: ${field.options.join(", ")}`);
      }
    }
  }
  return { valid: errors.length === 0, errors };
}

