function getJurisdictions() {
  return Object.values(JURISDICTIONS);
}
function getJurisdiction(code) {
  return JURISDICTIONS[code] || null;
}
function getJurisdictionsByRegion(region) {
  return Object.values(JURISDICTIONS).filter((j) => j.region === region);
}
function getTaxFavorableJurisdictions() {
  return Object.values(JURISDICTIONS).filter((j) => j.corporateTaxRate < 15);
}
function getTaxTreaty(country1, country2) {
  return TAX_TREATIES.find(
    (t2) => t2.country1 === country1 && t2.country2 === country2 || t2.country1 === country2 && t2.country2 === country1
  ) || null;
}
function getTaxTreatiesForCountry(countryCode) {
  return TAX_TREATIES.filter(
    (t2) => t2.country1 === countryCode || t2.country2 === countryCode
  );
}
