function getAllLogEntries() {
  return [...autoLogEntries].sort(
    (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
  );
}
function getLogEntriesByEntity(entityId) {
  return autoLogEntries.filter((e) => e.entityId === entityId).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
}
function getLogEntriesByCategory(category) {
  return autoLogEntries.filter((e) => e.category === category).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
}
function getLogEntriesByEventType(eventType) {
  return autoLogEntries.filter((e) => e.eventType === eventType).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
}
function getLogEntriesByDateRange(startDate, endDate) {
  const start = new Date(startDate).getTime();
  const end = new Date(endDate).getTime();
  return autoLogEntries.filter((e) => {
    const timestamp2 = new Date(e.timestamp).getTime();
    return timestamp2 >= start && timestamp2 <= end;
  }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
}
function getLogEntryById(logId) {
  return autoLogEntries.find((e) => e.id === logId) || null;
}
function updateLogEntryStatus(logId, status) {
  const entry = autoLogEntries.find((e) => e.id === logId);
  if (entry) {
    entry.status = status;
    return entry;
  }
  return null;
}
function getEventConfig(eventType) {
  return EVENT_CONFIGS[eventType];
}
function getAllEventConfigs() {
  return { ...EVENT_CONFIGS };
}
function getLogStatistics() {
  const byCategory = {};
  const byEventType = {};
  const byStatus = {};
  let totalInflows = 0;
  let totalOutflows = 0;
  for (const entry of autoLogEntries) {
    byCategory[entry.category] = (byCategory[entry.category] || 0) + 1;
    byEventType[entry.eventType] = (byEventType[entry.eventType] || 0) + 1;
    byStatus[entry.status] = (byStatus[entry.status] || 0) + 1;
    if (entry.financialImpact) {
      if (entry.financialImpact.direction === "inflow") {
        totalInflows += entry.financialImpact.amount;
      } else if (entry.financialImpact.direction === "outflow") {
        totalOutflows += entry.financialImpact.amount;
      }
    }
  }
  return {
    totalEntries: autoLogEntries.length,
    byCategory,
    byEventType,
    byStatus,
    financialSummary: {
      totalInflows,
      totalOutflows,
      netFlow: totalInflows - totalOutflows
    }
  };
}

