async function sendDonationThankYouEmail(donation) {
  try {
    const isRecurring = donation.frequency !== "one_time";
    const template = isRecurring ? generateRecurringThankYouEmail(donation) : generateOneTimeThankYouEmail(donation);
    console.log(`[DonorEmail] Sending thank-you email to ${donation.donorEmail}`);
    console.log(`[DonorEmail] Subject: ${template.subject}`);
    const formattedAmount = formatCurrency(donation.amount, donation.currency);
    const frequencyText = getFrequencyText(donation.frequency);
    await notifyOwner({
      title: `New ${frequencyText} Donation: ${formattedAmount}`,
      content: `
Donor: ${donation.isAnonymous ? "Anonymous" : donation.donorName}
Email: ${donation.donorEmail}
Amount: ${formattedAmount}
Frequency: ${frequencyText}
Designation: ${getDesignationText(donation.designation)}
${donation.tributeType && donation.tributeType !== "none" ? `Tribute: ${donation.tributeType === "in_honor" ? "In Honor of" : "In Memory of"} ${donation.tributeName}` : ""}
Transaction ID: ${donation.transactionId}
      `.trim()
    });
    return {
      success: true,
      messageId: `msg_${Date.now()}_${Math.random().toString(36).slice(2)}`,
      timestamp: /* @__PURE__ */ new Date()
    };
  } catch (error) {
    console.error("[DonorEmail] Failed to send thank-you email:", error);
    return {
      success: false,
      error: error.message || "Failed to send email",
      timestamp: /* @__PURE__ */ new Date()
    };
  }
}
function getEmailTemplates() {
  return [
    { name: "one_time_thank_you", description: "Thank-you email for one-time donations" },
    { name: "recurring_thank_you", description: "Welcome email for new recurring donors" },
    { name: "recurring_payment", description: "Payment confirmation for recurring donations" },
    { name: "payment_failed", description: "Notification when a payment fails" }
  ];
}

// server/routers/donor-email.ts
var donationDetailsSchema = z211.object({
  donorName: z211.string(),
  donorEmail: z211.string().email(),
  amount: z211.number().positive(),
  currency: z211.string().default("USD"),
  frequency: z211.enum(["one_time", "monthly", "quarterly", "annual"]),
  designation: z211.string().optional(),
  tributeType: z211.enum(["none", "in_honor", "in_memory"]).optional(),
  tributeName: z211.string().optional(),
  transactionId: z211.string(),
  transactionDate: z211.string().transform((s) => new Date(s)),
  isAnonymous: z211.boolean().default(false)
});
var donorEmailRouter = router({
  /**
   * Get list of available email templates
   */
  getTemplates: publicProcedure.query(() => {
    return getEmailTemplates();
  }),
  /**
   * Preview an email template with sample data
   */
  previewTemplate: protectedProcedure.input(
    z211.object({
      templateType: z211.enum([
        "one_time_thank_you",
        "recurring_thank_you",
        "recurring_payment",
        "payment_failed"
      ]),
      donation: donationDetailsSchema.optional()
    })
  ).query(({ input }) => {
    const donation = input.donation || {
      donorName: "Sample Donor",
      donorEmail: "donor@example.com",
      amount: 100,
      currency: "USD",
      frequency: input.templateType.includes("recurring") ? "monthly" : "one_time",
      designation: "education",
      tributeType: "none",
      transactionId: "txn_sample123456",
      transactionDate: /* @__PURE__ */ new Date(),
      isAnonymous: false
    };
    switch (input.templateType) {
      case "one_time_thank_you":
        return generateOneTimeThankYouEmail(donation);
      case "recurring_thank_you":
        return generateRecurringThankYouEmail({ ...donation, frequency: donation.frequency === "one_time" ? "monthly" : donation.frequency });
      case "recurring_payment":
        return generateRecurringPaymentEmail({ ...donation, frequency: donation.frequency === "one_time" ? "monthly" : donation.frequency }, 1);
      case "payment_failed":
        return generatePaymentFailedEmail({ ...donation, frequency: donation.frequency === "one_time" ? "monthly" : donation.frequency });
      default:
        return generateOneTimeThankYouEmail(donation);
    }
  }),
  /**
   * Send a thank-you email for a donation
   */
  sendThankYou: protectedProcedure.input(donationDetailsSchema).mutation(async ({ input }) => {
    const result = await sendDonationThankYouEmail(input);
    return result;
  }),
  /**
   * Manually trigger thank-you email for a specific transaction
   */
  resendThankYou: protectedProcedure.input(
    z211.object({
      transactionId: z211.string(),
      donorEmail: z211.string().email(),
      donorName: z211.string(),
      amount: z211.number().positive(),
      frequency: z211.enum(["one_time", "monthly", "quarterly", "annual"]),
      transactionDate: z211.string().transform((s) => new Date(s))
    })
  ).mutation(async ({ input }) => {
    const donation = {
      ...input,
      currency: "USD",
      isAnonymous: false
    };
    const result = await sendDonationThankYouEmail(donation);
    return result;
  })
});

