function getEntityInfo(entityType) {
  return entityInfo[entityType] || null;
}
function generateCoverLetter(data) {
  const template = grantTemplates[data.templateType];
  const entity = entityInfo[data.entityType];
  return `${(/* @__PURE__ */ new Date()).toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" })}

${template.organization}
Grant Programs Office

RE: ${template.name} Application - ${data.projectTitle}

Dear Grant Review Committee,

On behalf of ${data.organizationName}, I am pleased to submit this application for the ${template.name} in the amount of $${data.requestedAmount.toLocaleString()}.

${entity.missionStatement}. This project, "${data.projectTitle}," directly advances our mission by ${data.projectSummary || "creating meaningful impact in our community"}.

Our organization has demonstrated a strong track record of successful program delivery and fiscal responsibility. We are confident that this investment will generate significant returns for the communities we serve.

We welcome the opportunity to discuss this proposal further and provide any additional information you may require.

Respectfully submitted,

${data.applicantName}
${data.applicantTitle}
${data.organizationName}
${data.organizationPhone}
${data.organizationEmail}`;
}
function generateBudgetNarrative(budgetItems) {
  const total = budgetItems.reduce((sum5, item) => sum5 + item.amount, 0);
  const categoryTotals = {};
  budgetItems.forEach((item) => {
    categoryTotals[item.category] = (categoryTotals[item.category] || 0) + item.amount;
  });
  let narrative = `BUDGET NARRATIVE

Total Project Budget: $${total.toLocaleString()}

`;
  narrative += `BUDGET SUMMARY BY CATEGORY
${"=".repeat(50)}

`;
  Object.entries(categoryTotals).forEach(([category, amount]) => {
    const percentage = (amount / total * 100).toFixed(1);
    narrative += `${category}: $${amount.toLocaleString()} (${percentage}%)
`;
  });
  narrative += `

DETAILED LINE ITEMS
${"=".repeat(50)}

`;
  budgetItems.forEach((item, index2) => {
    narrative += `${index2 + 1}. ${item.description}
`;
    narrative += `   Category: ${item.category}
`;
    narrative += `   Amount: $${item.amount.toLocaleString()}
`;
    narrative += `   Justification: ${item.justification}

`;
  });
  return narrative;
}
function generateBudgetTable(budgetItems) {
  const total = budgetItems.reduce((sum5, item) => sum5 + item.amount, 0);
  let table = `| Category | Description | Amount | % of Total |
`;
  table += `|----------|-------------|--------|------------|
`;
  budgetItems.forEach((item) => {
    const percentage = (item.amount / total * 100).toFixed(1);
    table += `| ${item.category} | ${item.description} | $${item.amount.toLocaleString()} | ${percentage}% |
`;
  });
  table += `| **TOTAL** | | **$${total.toLocaleString()}** | **100%** |
`;
  return table;
}
function generateOrganizationalBackground(entityType) {
  const entity = entityInfo[entityType];
  const needStatement = getNeedStatement(entityType);
  return `ORGANIZATIONAL BACKGROUND

Legal Name: ${entity.legalName}
Tax Status: ${entity.taxStatus}
EIN: ${entity.ein}

Address: ${entity.address}
Phone: ${entity.phone}
Email: ${entity.email}
Website: ${entity.website}

MISSION STATEMENT
${entity.missionStatement}

ORGANIZATIONAL HISTORY AND CAPACITY
${needStatement?.proofOfConcept || "Our organization has a proven track record of successful program delivery and community impact."}

KEY ACCOMPLISHMENTS
${needStatement?.targetPopulation ? `We serve ${needStatement.targetPopulation}, providing essential services and support.` : "We have successfully served our target population through innovative programming."}`;
}
function generateGrantApplication(data) {
  const template = grantTemplates[data.templateType];
  const needStatement = getNeedStatement(data.entityType);
  const entity = entityInfo[data.entityType];
  const sections = [];
  let order = 1;
  sections.push({
    title: "Cover Letter",
    content: generateCoverLetter(data),
    order: order++
  });
  sections.push({
    title: "Executive Summary",
    content: `PROJECT: ${data.projectTitle}
ORGANIZATION: ${data.organizationName}
AMOUNT REQUESTED: $${data.requestedAmount.toLocaleString()}
PROJECT PERIOD: ${data.projectStartDate} to ${data.projectEndDate}

${data.projectSummary || needStatement?.summary || "This project will create meaningful impact in our community through innovative programming and sustainable practices."}`,
    order: order++
  });
  sections.push({
    title: "Statement of Need",
    content: data.customNeedStatement || needStatement?.fullStatement || "A detailed need statement demonstrating the critical importance of this project.",
    order: order++
  });
  sections.push({
    title: "Project Description",
    content: `PROJECT GOALS AND OBJECTIVES

${needStatement?.fundingRequest || `This project seeks $${data.requestedAmount.toLocaleString()} to implement transformative programming.`}

METHODOLOGY AND APPROACH

Our approach combines evidence-based practices with community-centered design to ensure maximum impact and sustainability.

TIMELINE

Start Date: ${data.projectStartDate}
End Date: ${data.projectEndDate}

KEY MILESTONES
- Month 1-3: Planning and infrastructure development
- Month 4-6: Program launch and initial implementation
- Month 7-9: Expansion and community engagement
- Month 10-12: Evaluation and sustainability planning`,
    order: order++
  });
  sections.push({
    title: "Organizational Background",
    content: generateOrganizationalBackground(data.entityType),
    order: order++
  });
  const budgetContent = data.budgetItems.length > 0 ? generateBudgetNarrative(data.budgetItems) : generateDefaultBudget(data.requestedAmount, data.entityType);
  sections.push({
    title: "Budget",
    content: budgetContent,
    order: order++
  });
  sections.push({
    title: "Evaluation Plan",
    content: `EVALUATION METHODOLOGY

We will employ a mixed-methods evaluation approach combining quantitative metrics with qualitative assessments.

KEY PERFORMANCE INDICATORS
- Number of participants served
- Program completion rates
- Participant satisfaction scores
- Long-term outcome tracking (6-month and 12-month follow-up)

DATA COLLECTION METHODS
- Pre/post assessments
- Participant surveys
- Focus groups
- Administrative data tracking

REPORTING
Quarterly progress reports will be submitted to the funder, with a comprehensive final report upon project completion.`,
    order: order++
  });
  sections.push({
    title: "Sustainability Plan",
    content: `LONG-TERM SUSTAINABILITY

This project is designed for long-term sustainability through:

1. DIVERSIFIED FUNDING
   - Earned revenue from program fees
   - Corporate partnerships
   - Individual donor cultivation
   - Government contracts

2. ORGANIZATIONAL CAPACITY
   - Staff training and development
   - Systems and infrastructure investment
   - Community partnership development

3. PROGRAM INTEGRATION
   - Integration with existing organizational programs
   - Community ownership and engagement
   - Scalable program model`,
    order: order++
  });
  return {
    id: `grant_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    entityType: data.entityType,
    templateType: data.templateType,
    generatedAt: Date.now(),
    sections,
    totalBudget: data.budgetItems.reduce((sum5, item) => sum5 + item.amount, 0) || data.requestedAmount,
    metadata: {
      organizationName: data.organizationName || entity.legalName,
      projectTitle: data.projectTitle,
      requestedAmount: data.requestedAmount,
      templateName: template.name
    }
  };
}
function generateDefaultBudget(amount, entityType) {
  const budgetItems = [];
  switch (entityType) {
    case "real_eye_nation":
      budgetItems.push(
        { category: "Personnel", description: "Production Staff", amount: Math.round(amount * 0.35), justification: "Director, cinematographer, editor, and production assistants" },
        { category: "Equipment", description: "Production Equipment", amount: Math.round(amount * 0.25), justification: "Cameras, lighting, audio equipment, and editing systems" },
        { category: "Production", description: "Production Costs", amount: Math.round(amount * 0.2), justification: "Location fees, travel, materials, and post-production" },
        { category: "Distribution", description: "Distribution & Marketing", amount: Math.round(amount * 0.12), justification: "Film festival submissions, marketing, and distribution" },
        { category: "Admin", description: "Administrative Overhead", amount: Math.round(amount * 0.08), justification: "Insurance, legal, accounting, and office expenses" }
      );
      break;
    case "laws_collective":
      budgetItems.push(
        { category: "Personnel", description: "Program Staff", amount: Math.round(amount * 0.4), justification: "Program managers, trainers, and support staff" },
        { category: "Technology", description: "Platform Development", amount: Math.round(amount * 0.25), justification: "SaaS platform development and maintenance" },
        { category: "Facilities", description: "Hub Operations", amount: Math.round(amount * 0.18), justification: "Regional hub facilities and equipment" },
        { category: "Programs", description: "Training Programs", amount: Math.round(amount * 0.1), justification: "Curriculum development and training materials" },
        { category: "Admin", description: "Administrative Overhead", amount: Math.round(amount * 0.07), justification: "Insurance, legal, accounting, and office expenses" }
      );
      break;
    case "luvonpurpose_aws":
      budgetItems.push(
        { category: "Technology", description: "Platform Infrastructure", amount: Math.round(amount * 0.35), justification: "Cloud infrastructure, security, and development" },
        { category: "Personnel", description: "Development Team", amount: Math.round(amount * 0.3), justification: "Software engineers, designers, and product managers" },
        { category: "Programs", description: "Financial Literacy Programs", amount: Math.round(amount * 0.18), justification: "Curriculum development and community outreach" },
        { category: "Marketing", description: "Community Engagement", amount: Math.round(amount * 0.1), justification: "Marketing, partnerships, and user acquisition" },
        { category: "Admin", description: "Administrative Overhead", amount: Math.round(amount * 0.07), justification: "Insurance, legal, accounting, and office expenses" }
      );
      break;
    case "508_academy":
      budgetItems.push(
        { category: "Personnel", description: "Educational Staff", amount: Math.round(amount * 0.45), justification: "Teachers, administrators, and support staff" },
        { category: "Facilities", description: "Facility Operations", amount: Math.round(amount * 0.2), justification: "Facility maintenance, utilities, and equipment" },
        { category: "Programs", description: "Curriculum & Materials", amount: Math.round(amount * 0.18), justification: "Curriculum development, textbooks, and supplies" },
        { category: "Technology", description: "Educational Technology", amount: Math.round(amount * 0.1), justification: "Computers, software, and learning management systems" },
        { category: "Admin", description: "Administrative Overhead", amount: Math.round(amount * 0.07), justification: "Insurance, legal, accounting, and office expenses" }
      );
      break;
  }
  return generateBudgetNarrative(budgetItems);
}
function exportToMarkdown(application) {
  let markdown = `# Grant Application: ${application.metadata.projectTitle}

`;
  markdown += `**Organization:** ${application.metadata.organizationName}
`;
  markdown += `**Template:** ${application.metadata.templateName}
`;
  markdown += `**Amount Requested:** $${application.metadata.requestedAmount.toLocaleString()}
`;
  markdown += `**Generated:** ${new Date(application.generatedAt).toLocaleDateString()}

`;
  markdown += `---

`;
  application.sections.forEach((section) => {
    markdown += `## ${section.title}

`;
    markdown += `${section.content}

`;
    markdown += `---

`;
  });
  return markdown;
}
function exportToJSON(application) {
  return JSON.stringify(application, null, 2);
}
function getApplicationChecklist(templateType) {
  const template = grantTemplates[templateType];
  const checklist = [
    { item: "Cover Letter", required: true, description: "Signed letter from authorized representative" },
    { item: "Executive Summary", required: true, description: "One-page project overview" },
    { item: "Need Statement", required: true, description: "Documentation of community need" },
    { item: "Project Description", required: true, description: "Detailed project plan with timeline" },
    { item: "Budget", required: true, description: "Detailed line-item budget with narrative" },
    { item: "Organizational Background", required: true, description: "History and capacity documentation" }
  ];
  template.requiredDocuments.forEach((doc) => {
    checklist.push({
      item: doc,
      required: true,
      description: `Required supporting document: ${doc}`
    });
  });
  return checklist;
}

// server/routers/grant-export.ts
var entityTypeSchema = z229.enum(["real_eye_nation", "laws_collective", "luvonpurpose_aws", "508_academy"]);
var templateTypeSchema = z229.enum([
  "federal_nea",
  "federal_usda",
  "federal_sba",
  "foundation_ford",
  "foundation_kellogg",
  "foundation_macarthur",
  "generic"
]);
var budgetItemSchema = z229.object({
  category: z229.string(),
  description: z229.string(),
  amount: z229.number(),
  justification: z229.string()
});
var grantApplicationDataSchema = z229.object({
  entityType: entityTypeSchema,
  templateType: templateTypeSchema,
  applicantName: z229.string(),
  applicantTitle: z229.string(),
  organizationName: z229.string(),
  organizationAddress: z229.string(),
  organizationPhone: z229.string(),
  organizationEmail: z229.string(),
  organizationWebsite: z229.string().optional(),
  einNumber: z229.string(),
  dunsNumber: z229.string().optional(),
  requestedAmount: z229.number(),
  projectTitle: z229.string(),
  projectStartDate: z229.string(),
  projectEndDate: z229.string(),
  projectSummary: z229.string().optional(),
  customNeedStatement: z229.string().optional(),
  budgetItems: z229.array(budgetItemSchema),
  additionalDocuments: z229.array(z229.string()).optional()
});
var grantExportRouter = router({
  /**
   * Get all available grant templates
   */
  getTemplates: publicProcedure.query(() => {
    return getGrantTemplates();
  }),
  /**
   * Get templates eligible for a specific entity
   */
  getTemplatesForEntity: publicProcedure.input(z229.object({ entityType: entityTypeSchema })).query(({ input }) => {
    return getTemplatesForEntity(input.entityType);
  }),
  /**
   * Get a specific grant template by ID
   */
  getTemplate: publicProcedure.input(z229.object({ templateType: templateTypeSchema })).query(({ input }) => {
    return getGrantTemplate(input.templateType);
  }),
  /**
   * Get entity information for pre-filling forms
   */
  getEntityInfo: publicProcedure.input(z229.object({ entityType: entityTypeSchema })).query(({ input }) => {
    return getEntityInfo(input.entityType);
  }),
  /**
   * Get need statement for auto-population
   */
  getNeedStatement: publicProcedure.input(z229.object({ entityType: entityTypeSchema })).query(({ input }) => {
    return getNeedStatement(input.entityType);
  }),
  /**
   * Get all need statements
   */
  getAllNeedStatements: publicProcedure.query(() => {
    return getAllNeedStatements();
  }),
  /**
   * Generate a complete grant application
   */
  generateApplication: publicProcedure.input(grantApplicationDataSchema).mutation(({ input }) => {
    return generateGrantApplication(input);
  }),
  /**
   * Generate just the cover letter
   */
  generateCoverLetter: publicProcedure.input(grantApplicationDataSchema).mutation(({ input }) => {
    return generateCoverLetter(input);
  }),
  /**
   * Generate budget table in markdown format
   */
  generateBudgetTable: publicProcedure.input(z229.object({ budgetItems: z229.array(budgetItemSchema) })).mutation(({ input }) => {
    return generateBudgetTable(input.budgetItems);
  }),
  /**
   * Generate budget narrative
   */
  generateBudgetNarrative: publicProcedure.input(z229.object({ budgetItems: z229.array(budgetItemSchema) })).mutation(({ input }) => {
    return generateBudgetNarrative(input.budgetItems);
  }),
  /**
   * Generate organizational background section
   */
  generateOrgBackground: publicProcedure.input(z229.object({ entityType: entityTypeSchema })).mutation(({ input }) => {
    return generateOrganizationalBackground(input.entityType);
  }),
  /**
   * Export application to markdown
   */
  exportToMarkdown: publicProcedure.input(grantApplicationDataSchema).mutation(({ input }) => {
    const application = generateGrantApplication(input);
    return {
      markdown: exportToMarkdown(application),
      application
    };
  }),
  /**
   * Export application to JSON
   */
  exportToJSON: publicProcedure.input(grantApplicationDataSchema).mutation(({ input }) => {
    const application = generateGrantApplication(input);
    return {
      json: exportToJSON(application),
      application
    };
  }),
  /**
   * Get application checklist for a template
   */
  getChecklist: publicProcedure.input(z229.object({ templateType: templateTypeSchema })).query(({ input }) => {
    return getApplicationChecklist(input.templateType);
  }),
  /**
   * Get pre-filled application data for an entity
   */
  getPrefilledData: publicProcedure.input(z229.object({
    entityType: entityTypeSchema,
    templateType: templateTypeSchema
  })).query(({ input }) => {
    const entityInfo2 = getEntityInfo(input.entityType);
    const needStatement = getNeedStatement(input.entityType);
    const template = getGrantTemplate(input.templateType);
    if (!entityInfo2 || !template) {
      return null;
    }
    return {
      entityType: input.entityType,
      templateType: input.templateType,
      organizationName: entityInfo2.legalName,
      organizationAddress: entityInfo2.address,
      organizationPhone: entityInfo2.phone,
      organizationEmail: entityInfo2.email,
      organizationWebsite: entityInfo2.website,
      einNumber: entityInfo2.ein,
      taxStatus: entityInfo2.taxStatus,
      missionStatement: entityInfo2.missionStatement,
      needStatement: needStatement?.fullStatement || "",
      fundingRange: needStatement?.fundingRequest || "",
      suggestedAmount: needStatement?.fundingAmount?.min || template.maxFunding * 0.5,
      maxFunding: template.maxFunding,
      templateName: template.name,
      requiredDocuments: template.requiredDocuments,
      deadlineInfo: template.deadlineInfo
    };
  }),
  /**
   * Validate application data before submission
   */
  validateApplication: publicProcedure.input(grantApplicationDataSchema.partial()).mutation(({ input }) => {
    const errors = [];
    if (!input.entityType) {
      errors.push({ field: "entityType", message: "Entity type is required" });
    }
    if (!input.templateType) {
      errors.push({ field: "templateType", message: "Template type is required" });
    }
    if (!input.applicantName) {
      errors.push({ field: "applicantName", message: "Applicant name is required" });
    }
    if (!input.projectTitle) {
      errors.push({ field: "projectTitle", message: "Project title is required" });
    }
    if (!input.requestedAmount || input.requestedAmount <= 0) {
      errors.push({ field: "requestedAmount", message: "Valid requested amount is required" });
    }
    if (!input.projectStartDate) {
      errors.push({ field: "projectStartDate", message: "Project start date is required" });
    }
    if (!input.projectEndDate) {
      errors.push({ field: "projectEndDate", message: "Project end date is required" });
    }
    if (input.budgetItems && input.budgetItems.length > 0) {
      const totalBudget = input.budgetItems.reduce((sum5, item) => sum5 + (item.amount || 0), 0);
      if (input.requestedAmount && Math.abs(totalBudget - input.requestedAmount) > 1) {
        errors.push({
          field: "budgetItems",
          message: `Budget total ($${totalBudget.toLocaleString()}) does not match requested amount ($${input.requestedAmount?.toLocaleString()})`
        });
      }
    }
    return {
      valid: errors.length === 0,
      errors
    };
  })
});

