// server/routers/vod.ts
init_db();
import { z as z273 } from "zod";
var vodRouter = router({
  /**
   * Get all VOD movies with filtering
   */
  getMovies: publicProcedure.input(
    z273.object({
      genre: z273.string().optional(),
      contentRating: z273.enum(["G", "PG", "PG-13", "R", "NC-17", "X", "UNRATED"]).optional(),
      accessLevel: z273.enum(["public", "members", "verified_18", "verified_21", "premium"]).optional(),
      limit: z273.number().default(50),
      offset: z273.number().default(0),
      sortBy: z273.enum(["newest", "rating", "views", "trending"]).default("newest")
    })
  ).query(async ({ input, ctx }) => {
    try {
      const movies = await db.query.vodMovies.findMany({
        limit: input.limit,
        offset: input.offset
      });
      if (input.genre) {
        return movies.filter((m) => m.genre === input.genre);
      }
      if (input.sortBy === "rating") {
        return movies.sort((a, b) => (b.imdbRating || 0) - (a.imdbRating || 0));
      } else if (input.sortBy === "views") {
        return movies.sort((a, b) => (b.viewCount || 0) - (a.viewCount || 0));
      }
      return movies;
    } catch (error) {
      console.error("Error fetching movies:", error);
      return [];
    }
  }),
  /**
   * Get all VOD series with filtering
   */
  getSeries: publicProcedure.input(
    z273.object({
      genre: z273.string().optional(),
      contentRating: z273.enum(["G", "PG", "PG-13", "R", "NC-17", "X", "UNRATED"]).optional(),
      status: z273.enum(["ongoing", "completed", "cancelled"]).optional(),
      limit: z273.number().default(50),
      offset: z273.number().default(0)
    })
  ).query(async ({ input, ctx }) => {
    try {
      const series = await db.query.vodSeries.findMany({
        limit: input.limit,
        offset: input.offset
      });
      if (input.genre) {
        return series.filter((s) => s.genre === input.genre);
      }
      if (input.status) {
        return series.filter((s) => s.status === input.status);
      }
      return series;
    } catch (error) {
      console.error("Error fetching series:", error);
      return [];
    }
  }),
  /**
   * Get movie details
   */
  getMovieDetails: publicProcedure.input(z273.object({ movieId: z273.number() })).query(async ({ input, ctx }) => {
    try {
      const movie = await db.query.vodMovies.findFirst({
        where: (movies, { eq: eq159 }) => eq159(movies.id, input.movieId)
      });
      if (!movie) {
        throw new Error("Movie not found");
      }
      const reviews = await db.query.vodReviews.findMany({
        where: (reviews2, { eq: eq159 }) => eq159(reviews2.movieId, input.movieId),
        limit: 10
      });
      return {
        ...movie,
        reviews
      };
    } catch (error) {
      console.error("Error fetching movie details:", error);
      throw error;
    }
  }),
  /**
   * Get series details with episodes
   */
  getSeriesDetails: publicProcedure.input(z273.object({ seriesId: z273.number() })).query(async ({ input, ctx }) => {
    try {
      const series = await db.query.vodSeries.findFirst({
        where: (series2, { eq: eq159 }) => eq159(series2.id, input.seriesId)
      });
      if (!series) {
        throw new Error("Series not found");
      }
      const episodes = await db.query.vodEpisodes.findMany({
        where: (eps, { eq: eq159 }) => eq159(eps.seriesId, input.seriesId),
        limit: 100
      });
      const reviews = await db.query.vodReviews.findMany({
        where: (reviews2, { eq: eq159 }) => eq159(reviews2.seriesId, input.seriesId),
        limit: 10
      });
      return {
        ...series,
        episodes,
        reviews
      };
    } catch (error) {
      console.error("Error fetching series details:", error);
      throw error;
    }
  }),
  /**
   * Get episodes for a series
   */
  getEpisodes: publicProcedure.input(
    z273.object({
      seriesId: z273.number(),
      seasonNumber: z273.number().optional(),
      limit: z273.number().default(50),
      offset: z273.number().default(0)
    })
  ).query(async ({ input, ctx }) => {
    try {
      const episodes = await db.query.vodEpisodes.findMany({
        limit: input.limit,
        offset: input.offset
      });
      if (input.seasonNumber) {
        return episodes.filter((e) => e.seasonNumber === input.seasonNumber);
      }
      return episodes;
    } catch (error) {
      console.error("Error fetching episodes:", error);
      return [];
    }
  }),
  /**
   * Add movie to watchlist
   */
  addToWatchlist: protectedProcedure.input(
    z273.object({
      movieId: z273.number().optional(),
      seriesId: z273.number().optional(),
      priority: z273.number().default(0)
    })
  ).mutation(async ({ input, ctx }) => {
    try {
      const result = await db.insert(vodWatchlist).values({
        userId: ctx.user.id,
        movieId: input.movieId || null,
        seriesId: input.seriesId || null,
        priority: input.priority
      });
      return {
        success: true,
        watchlistId: result.insertId,
        message: "Added to watchlist"
      };
    } catch (error) {
      console.error("Error adding to watchlist:", error);
      throw error;
    }
  }),
  /**
   * Get user's watchlist
   */
  getWatchlist: protectedProcedure.input(
    z273.object({
      limit: z273.number().default(50),
      offset: z273.number().default(0)
    })
  ).query(async ({ input, ctx }) => {
    try {
      const watchlist = await db.query.vodWatchlist.findMany({
        where: (w, { eq: eq159 }) => eq159(w.userId, ctx.user.id),
        limit: input.limit,
        offset: input.offset
      });
      return watchlist;
    } catch (error) {
      console.error("Error fetching watchlist:", error);
      return [];
    }
  }),
  /**
   * Start watching (track viewing history)
   */
  startWatching: protectedProcedure.input(
    z273.object({
      movieId: z273.number().optional(),
      episodeId: z273.number().optional()
    })
  ).mutation(async ({ input, ctx }) => {
    try {
      const result = await db.insert(vodViewingHistory).values({
        userId: ctx.user.id,
        movieId: input.movieId || null,
        episodeId: input.episodeId || null,
        startTime: /* @__PURE__ */ new Date()
      });
      return {
        success: true,
        historyId: result.insertId,
        message: "Viewing started"
      };
    } catch (error) {
      console.error("Error starting viewing:", error);
      throw error;
    }
  }),
  /**
   * Update viewing progress
   */
  updateProgress: protectedProcedure.input(
    z273.object({
      historyId: z273.number(),
      progress: z273.number().min(0).max(100),
      duration: z273.number()
    })
  ).mutation(async ({ input, ctx }) => {
    try {
      const isCompleted = input.progress >= 90;
      await db.update(vodViewingHistory).set({
        progress: input.progress,
        duration: input.duration,
        isCompleted
      }).where((h) => h.id === input.historyId);
      return {
        success: true,
        message: "Progress updated"
      };
    } catch (error) {
      console.error("Error updating progress:", error);
      throw error;
    }
  }),
  /**
   * Get viewing history
   */
  getViewingHistory: protectedProcedure.input(
    z273.object({
      limit: z273.number().default(50),
      offset: z273.number().default(0)
    })
  ).query(async ({ input, ctx }) => {
    try {
      const history = await db.query.vodViewingHistory.findMany({
        where: (h, { eq: eq159 }) => eq159(h.userId, ctx.user.id),
        limit: input.limit,
        offset: input.offset
      });
      return history;
    } catch (error) {
      console.error("Error fetching viewing history:", error);
      return [];
    }
  }),
  /**
   * Add review/rating
   */
  addReview: protectedProcedure.input(
    z273.object({
      movieId: z273.number().optional(),
      seriesId: z273.number().optional(),
      rating: z273.number().min(1).max(5),
      reviewText: z273.string().optional()
    })
  ).mutation(async ({ input, ctx }) => {
    try {
      const result = await db.insert(vodReviews).values({
        userId: ctx.user.id,
        movieId: input.movieId || null,
        seriesId: input.seriesId || null,
        rating: input.rating,
        reviewText: input.reviewText
      });
      return {
        success: true,
        reviewId: result.insertId,
        message: "Review added"
      };
    } catch (error) {
      console.error("Error adding review:", error);
      throw error;
    }
  }),
  /**
   * Search VOD content
   */
  search: publicProcedure.input(
    z273.object({
      query: z273.string().min(1),
      type: z273.enum(["movie", "series", "all"]).default("all"),
      limit: z273.number().default(20)
    })
  ).query(async ({ input, ctx }) => {
    try {
      const results = {
        movies: [],
        series: []
      };
      if (input.type === "movie" || input.type === "all") {
        const movies = await db.query.vodMovies.findMany({
          limit: input.limit
        });
        results.movies = movies.filter(
          (m) => m.title.toLowerCase().includes(input.query.toLowerCase()) || m.director?.toLowerCase().includes(input.query.toLowerCase())
        );
      }
      if (input.type === "series" || input.type === "all") {
        const series = await db.query.vodSeries.findMany({
          limit: input.limit
        });
        results.series = series.filter(
          (s) => s.title.toLowerCase().includes(input.query.toLowerCase()) || s.creator?.toLowerCase().includes(input.query.toLowerCase())
        );
      }
      return results;
    } catch (error) {
      console.error("Error searching VOD:", error);
      throw error;
    }
  }),
  /**
   * Get trending movies
   */
  getTrendingMovies: publicProcedure.input(z273.object({ limit: z273.number().default(10) })).query(async ({ input, ctx }) => {
    try {
      const movies = await db.query.vodMovies.findMany({
        limit: input.limit
      });
      return movies.sort((a, b) => (b.viewCount || 0) - (a.viewCount || 0));
    } catch (error) {
      console.error("Error fetching trending movies:", error);
      return [];
    }
  }),
  /**
   * Get featured content
   */
  getFeaturedContent: publicProcedure.query(async ({ ctx }) => {
    try {
      const topMovies = await db.query.vodMovies.findMany({
        limit: 5
      });
      const topSeries = await db.query.vodSeries.findMany({
        limit: 5
      });
      return {
        movies: topMovies.sort((a, b) => (b.imdbRating || 0) - (a.imdbRating || 0)),
        series: topSeries.sort((a, b) => (b.imdbRating || 0) - (a.imdbRating || 0))
      };
    } catch (error) {
      console.error("Error fetching featured content:", error);
      return { movies: [], series: [] };
    }
  })
});

