// server/routers/department-dashboard.ts
import { z as z300 } from "zod";
init_db();
init_departmentRegistry();
var departmentDashboardRouter = router({
  /**
   * Get the full department registry (all departments with their mappings)
   */
  getRegistry: protectedProcedure.query(async () => {
    return {
      departments: DEPARTMENT_REGISTRY,
      stats: getRegistryStats()
    };
  }),
  /**
   * Get a single department's full context
   */
  getDepartment: protectedProcedure.input(z300.object({ departmentId: z300.string() })).query(async ({ input }) => {
    const dept = getDepartment(input.departmentId);
    if (!dept) return null;
    return dept;
  }),
  /**
   * Get simulator completion stats for a specific department
   * Shows how many users have completed each of the department's simulators
   */
  getDepartmentSimulatorStats: protectedProcedure.input(z300.object({ departmentId: z300.string() })).query(async ({ input }) => {
    const dept = getDepartment(input.departmentId);
    if (!dept) return { department: null, simulators: [] };
    const simulatorStats = [];
    for (const sim of dept.simulators) {
      try {
        const result = await db.execute({
          sql: `SELECT 
                    COUNT(*) as totalCompletions,
                    AVG(score) as avgScore,
                    MAX(completedAt) as lastCompletion
                  FROM simulator_completion 
                  WHERE simulatorType = ?`,
          args: [sim.type]
        });
        const row = result.rows[0];
        simulatorStats.push({
          type: sim.type,
          label: sim.label,
          route: sim.route,
          certificateType: sim.certificateType,
          totalCompletions: Number(row?.totalCompletions ?? 0),
          avgScore: row?.avgScore ? Math.round(Number(row.avgScore)) : null,
          lastCompletion: row?.lastCompletion ?? null
        });
      } catch {
        simulatorStats.push({
          type: sim.type,
          label: sim.label,
          route: sim.route,
          certificateType: sim.certificateType,
          totalCompletions: 0,
          avgScore: null,
          lastCompletion: null
        });
      }
    }
    return {
      department: {
        id: dept.id,
        name: dept.name,
        manager: dept.manager,
        entity: dept.entity
      },
      simulators: simulatorStats
    };
  }),
  /**
   * Get certificates issued under a specific department
   */
  getDepartmentCertificates: protectedProcedure.input(
    z300.object({
      departmentId: z300.string(),
      limit: z300.number().min(1).max(100).optional()
    })
  ).query(async ({ input }) => {
    const dept = getDepartment(input.departmentId);
    if (!dept) return { certificates: [], total: 0 };
    const limit = input.limit ?? 20;
    try {
      const result = await db.execute({
        sql: `SELECT br.id, br.blockchainHash, br.data, br.createdAt
                FROM blockchain_records br
                WHERE br.recordType = 'certificate'
                AND JSON_EXTRACT(br.data, '$.departmentId') = ?
                ORDER BY br.createdAt DESC
                LIMIT ?`,
        args: [input.departmentId, limit]
      });
      const certificates4 = result.rows.map((row) => {
        const data = typeof row.data === "string" ? JSON.parse(row.data) : row.data;
        return {
          id: row.id,
          blockchainHash: row.blockchainHash,
          userName: data?.userName ?? "Unknown",
          simulatorLabel: data?.simulatorLabel ?? "Unknown",
          score: data?.score ?? null,
          issuedAt: data?.issuedAt ?? row.createdAt,
          signingManager: data?.signingManager ?? null
        };
      });
      const countResult = await db.execute({
        sql: `SELECT COUNT(*) as total FROM blockchain_records 
                WHERE recordType = 'certificate' 
                AND JSON_EXTRACT(data, '$.departmentId') = ?`,
        args: [input.departmentId]
      });
      const total = Number(countResult.rows[0]?.total ?? 0);
      return { certificates: certificates4, total };
    } catch {
      return { certificates: [], total: 0 };
    }
  }),
  /**
   * Get all departments with their simulator stats (overview for admin/CEO)
   */
  getAllDepartmentStats: protectedProcedure.query(async () => {
    const departmentsWithSims = getDepartmentsWithSimulators();
    const stats = [];
    for (const dept of departmentsWithSims) {
      let totalCompletions = 0;
      for (const sim of dept.simulators) {
        try {
          const result = await db.execute({
            sql: `SELECT COUNT(*) as cnt FROM simulator_completion WHERE simulatorType = ?`,
            args: [sim.type]
          });
          totalCompletions += Number(result.rows[0]?.cnt ?? 0);
        } catch {
        }
      }
      let totalCertificates = 0;
      try {
        const certResult = await db.execute({
          sql: `SELECT COUNT(*) as cnt FROM blockchain_records 
                WHERE recordType = 'certificate' 
                AND JSON_EXTRACT(data, '$.departmentId') = ?`,
          args: [dept.id]
        });
        totalCertificates = Number(certResult.rows[0]?.cnt ?? 0);
      } catch {
      }
      stats.push({
        departmentId: dept.id,
        departmentName: dept.name,
        manager: dept.manager,
        entity: dept.entity,
        color: dept.color,
        icon: dept.icon,
        simulatorCount: dept.simulators.length,
        totalCompletions,
        totalCertificates,
        dashboardRoute: dept.dashboardRoute
      });
    }
    return stats;
  }),
  /**
   * Get current user's certificates with full department context
   */
  getMyCertificates: protectedProcedure.query(async ({ ctx }) => {
    return getUserCertificatesWithDepartments(ctx.user.id);
  }),
  /**
   * Get training content items for a department (foundation for AI content builder)
   */
  getTrainingContent: protectedProcedure.input(z300.object({ departmentId: z300.string() })).query(async ({ input }) => {
    const dept = getDepartment(input.departmentId);
    if (!dept) return { content: [], department: null };
    try {
      const result = await db.execute({
        sql: `SELECT * FROM training_content 
                WHERE department = ? 
                ORDER BY updatedAt DESC 
                LIMIT 50`,
        args: [input.departmentId]
      });
      return {
        content: result.rows,
        department: { id: dept.id, name: dept.name, manager: dept.manager }
      };
    } catch {
      return {
        content: [],
        department: { id: dept.id, name: dept.name, manager: dept.manager }
      };
    }
  }),
  /**
   * Save or update training content for a department (AI content builder)
   */
  saveTrainingContent: protectedProcedure.input(
    z300.object({
      departmentId: z300.string(),
      title: z300.string().min(1),
      contentType: z300.enum(["lesson", "quiz", "exercise", "resource", "video_script"]),
      content: z300.string(),
      simulatorType: z300.string().optional(),
      metadata: z300.record(z300.any()).optional()
    })
  ).mutation(async ({ ctx, input }) => {
    const dept = getDepartment(input.departmentId);
    if (!dept) {
      return { success: false, error: "Department not found" };
    }
    try {
      await db.execute({
        sql: `CREATE TABLE IF NOT EXISTS training_content (
            id INT AUTO_INCREMENT PRIMARY KEY,
            department VARCHAR(100) NOT NULL,
            simulatorType VARCHAR(100),
            title VARCHAR(255) NOT NULL,
            contentType ENUM('lesson', 'quiz', 'exercise', 'resource', 'video_script') NOT NULL,
            content TEXT NOT NULL,
            createdBy INT NOT NULL,
            metadata JSON,
            status ENUM('draft', 'published', 'archived') DEFAULT 'draft',
            createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
          )`,
        args: []
      });
      const result = await db.execute({
        sql: `INSERT INTO training_content (department, simulatorType, title, contentType, content, createdBy, metadata, status)
                VALUES (?, ?, ?, ?, ?, ?, ?, 'draft')`,
        args: [
          input.departmentId,
          input.simulatorType ?? null,
          input.title,
          input.contentType,
          input.content,
          ctx.user.id,
          input.metadata ? JSON.stringify(input.metadata) : null
        ]
      });
      return {
        success: true,
        contentId: Number(result.insertId),
        message: `Training content "${input.title}" saved for ${dept.name} department.`
      };
    } catch (error) {
      return { success: false, error: error.message };
    }
  })
});

// server/routers/playlists.ts
init_db();
init_schema();
import { z as z301 } from "zod";
import { eq as eq150, and as and123, desc as desc117, asc as asc11 } from "drizzle-orm";
import { TRPCError as TRPCError72 } from "@trpc/server";
var playlistsRouter = router({
  // Get all playlists for the current user
  getMyPlaylists: protectedProcedure.query(async ({ ctx }) => {
    try {
      const playlists = await db.select().from(streamingPlaylists).where(eq150(streamingPlaylists.userId, ctx.user.id)).orderBy(desc117(streamingPlaylists.updatedAt));
      return playlists;
    } catch (error) {
      console.error("Error getting playlists:", error);
      return [];
    }
  }),
  // Get a single playlist with its items
  getPlaylist: protectedProcedure.input(z301.object({ id: z301.number() })).query(async ({ ctx, input }) => {
    const [playlist] = await db.select().from(streamingPlaylists).where(
      and123(
        eq150(streamingPlaylists.id, input.id),
        eq150(streamingPlaylists.userId, ctx.user.id)
      )
    ).limit(1);
    if (!playlist) {
      throw new TRPCError72({ code: "NOT_FOUND", message: "Playlist not found" });
    }
    const items = await db.select().from(playlistItems).where(eq150(playlistItems.playlistId, input.id)).orderBy(asc11(playlistItems.position));
    return { ...playlist, items };
  }),
  // Create a new playlist
  createPlaylist: protectedProcedure.input(
    z301.object({
      name: z301.string().min(1).max(255),
      description: z301.string().optional()
    })
  ).mutation(async ({ ctx, input }) => {
    const [result] = await db.insert(streamingPlaylists).values({
      userId: ctx.user.id,
      name: input.name,
      description: input.description || null,
      playlistType: "custom",
      itemCount: 0
    });
    return { id: result.insertId, name: input.name };
  }),
  // Update playlist metadata
  updatePlaylist: protectedProcedure.input(
    z301.object({
      id: z301.number(),
      name: z301.string().min(1).max(255).optional(),
      description: z301.string().optional()
    })
  ).mutation(async ({ ctx, input }) => {
    const [playlist] = await db.select().from(streamingPlaylists).where(
      and123(
        eq150(streamingPlaylists.id, input.id),
        eq150(streamingPlaylists.userId, ctx.user.id)
      )
    ).limit(1);
    if (!playlist) {
      throw new TRPCError72({ code: "NOT_FOUND", message: "Playlist not found" });
    }
    const updates = {};
    if (input.name) updates.name = input.name;
    if (input.description !== void 0) updates.description = input.description;
    await db.update(streamingPlaylists).set(updates).where(eq150(streamingPlaylists.id, input.id));
    return { success: true };
  }),
  // Delete a playlist
  deletePlaylist: protectedProcedure.input(z301.object({ id: z301.number() })).mutation(async ({ ctx, input }) => {
    const [playlist] = await db.select().from(streamingPlaylists).where(
      and123(
        eq150(streamingPlaylists.id, input.id),
        eq150(streamingPlaylists.userId, ctx.user.id)
      )
    ).limit(1);
    if (!playlist) {
      throw new TRPCError72({ code: "NOT_FOUND", message: "Playlist not found" });
    }
    await db.delete(streamingPlaylists).where(eq150(streamingPlaylists.id, input.id));
    return { success: true };
  }),
  // Add item to playlist
  addItem: protectedProcedure.input(
    z301.object({
      playlistId: z301.number(),
      contentId: z301.number(),
      contentType: z301.enum(["channel", "station"])
    })
  ).mutation(async ({ ctx, input }) => {
    const [playlist] = await db.select().from(streamingPlaylists).where(
      and123(
        eq150(streamingPlaylists.id, input.playlistId),
        eq150(streamingPlaylists.userId, ctx.user.id)
      )
    ).limit(1);
    if (!playlist) {
      throw new TRPCError72({ code: "NOT_FOUND", message: "Playlist not found" });
    }
    const items = await db.select().from(playlistItems).where(eq150(playlistItems.playlistId, input.playlistId));
    const nextPosition = items.length;
    await db.insert(playlistItems).values({
      playlistId: input.playlistId,
      contentId: input.contentId,
      contentType: input.contentType,
      position: nextPosition,
      addedBy: ctx.user.id
    });
    await db.update(streamingPlaylists).set({ itemCount: nextPosition + 1 }).where(eq150(streamingPlaylists.id, input.playlistId));
    return { success: true, position: nextPosition };
  }),
  // Remove item from playlist
  removeItem: protectedProcedure.input(
    z301.object({
      playlistId: z301.number(),
      itemId: z301.number()
    })
  ).mutation(async ({ ctx, input }) => {
    const [playlist] = await db.select().from(streamingPlaylists).where(
      and123(
        eq150(streamingPlaylists.id, input.playlistId),
        eq150(streamingPlaylists.userId, ctx.user.id)
      )
    ).limit(1);
    if (!playlist) {
      throw new TRPCError72({ code: "NOT_FOUND", message: "Playlist not found" });
    }
    await db.delete(playlistItems).where(eq150(playlistItems.id, input.itemId));
    const remaining = await db.select().from(playlistItems).where(eq150(playlistItems.playlistId, input.playlistId));
    await db.update(streamingPlaylists).set({ itemCount: remaining.length }).where(eq150(streamingPlaylists.id, input.playlistId));
    return { success: true };
  }),
  // Reorder items in playlist
  reorderItems: protectedProcedure.input(
    z301.object({
      playlistId: z301.number(),
      itemIds: z301.array(z301.number())
      // ordered array of item IDs
    })
  ).mutation(async ({ ctx, input }) => {
    const [playlist] = await db.select().from(streamingPlaylists).where(
      and123(
        eq150(streamingPlaylists.id, input.playlistId),
        eq150(streamingPlaylists.userId, ctx.user.id)
      )
    ).limit(1);
    if (!playlist) {
      throw new TRPCError72({ code: "NOT_FOUND", message: "Playlist not found" });
    }
    for (let i = 0; i < input.itemIds.length; i++) {
      await db.update(playlistItems).set({ position: i }).where(eq150(playlistItems.id, input.itemIds[i]));
    }
    return { success: true };
  }),
  // Get playlist items for autoplay (optionally shuffled)
  playAll: protectedProcedure.input(
    z301.object({
      playlistId: z301.number(),
      shuffle: z301.boolean().default(false)
    })
  ).query(async ({ ctx, input }) => {
    const [playlist] = await db.select().from(streamingPlaylists).where(
      and123(
        eq150(streamingPlaylists.id, input.playlistId),
        eq150(streamingPlaylists.userId, ctx.user.id)
      )
    ).limit(1);
    if (!playlist) {
      throw new TRPCError72({ code: "NOT_FOUND", message: "Playlist not found" });
    }
    let items = await db.select().from(playlistItems).where(eq150(playlistItems.playlistId, input.playlistId)).orderBy(asc11(playlistItems.position));
    if (input.shuffle && items.length > 0) {
      items = items.sort(() => Math.random() - 0.5);
    }
    return items;
  })
});

